prompt --application/pages/page_00001
begin
wwv_flow_imp_page.create_page(
 p_id=>1
,p_name=>unistr('In\00EDcio')
,p_alias=>'HOME'
,p_step_title=>'Senado Federal'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function debounce(func, wait) {',
'  let timeout;',
'  return function (...args) {',
'    const context = this;',
'    clearTimeout(timeout);',
'    timeout = setTimeout(() => func.apply(context, args), wait);',
'  };',
'}',
'',
'function removerAcentos(texto) {',
'  return texto.normalize("NFD").replace(/[\u0300-\u036f]/g, "");',
'}',
'',
'let visivel = false; // Define fora para escopo global',
unistr('const isAsqualog = $v(''P1_ASQUALOG'') === ''ASQUALOG'' || $v(''P1_ASQUALOG'') === ''SEQUALOG'' || $v(''P1_ASQUALOG'') === ''SEGEPAVI'' || $v(''P1_ASQUALOG'') === ''SEADD''; // Agora global tamb\00E9m'),
'',
'function aplicarEstiloCinza(card) {',
'  card.style.pointerEvents = ''auto'';',
'  card.style.cursor = ''not-allowed'';',
'  card.style.filter = ''grayscale(100%) brightness(1)'';',
'  card.style.borderRadius = ''6px'';',
'',
'  // Altera a cor de fundo da div com a classe .botao-icone',
'  const botaoIcone = card.querySelector(''.botao-icone'');',
'  if (botaoIcone) {',
'    botaoIcone.style.backgroundColor = ''#EAEAEA'';',
'  }',
'',
unistr('  // Altera a cor do \00EDcone dentro da classe .t-Icon'),
'  const icone = card.querySelector(''.t-Icon'');',
'  if (icone) {',
'    icone.style.color = ''#9AA1A7'';',
'  }',
'',
'  if (!card.dataset.listenerAdicionado) {',
'    card.addEventListener(''click'', (e) => {',
'      e.preventDefault();',
'      e.stopPropagation();',
unistr('      apex.message.alert("Este servi\00E7o n\00E3o est\00E1 habilitado para o seu perfil.");'),
'    });',
'    card.dataset.listenerAdicionado = ''true'';',
'  }',
'}',
'',
'function filtrarCards() {',
'  const termoBruto = document.querySelector(''.search-input'')?.value.trim().toLowerCase();',
'  const termo = removerAcentos(termoBruto);',
'  const todosCards = document.querySelectorAll(''.botao-wrapper'');',
'  const msgNenhum = document.getElementById(''mensagem-nenhum-encontrado'');',
'',
'  let algumVisivel = false;',
'',
'  todosCards.forEach(card => {',
'    const isCardAsqualog = card.classList.contains(''asqualog'');',
'    const texto = removerAcentos(card.textContent.trim().toLowerCase());',
'    const palavras = texto.split(/\s+/);',
'    const corresponde = !termo || palavras.some(palavra => palavra.startsWith(termo));',
'',
'    if (corresponde && (!isCardAsqualog || isAsqualog || visivel)) {',
'      card.style.display = ''flex'';',
'      if (!isAsqualog && isCardAsqualog && visivel) {',
'        aplicarEstiloCinza(card);',
'      } else {',
'        card.style.filter = '''';',
'        card.style.pointerEvents = '''';',
'        card.style.cursor = ''pointer'';',
'      }',
'      algumVisivel = true;',
'    } else {',
'      card.style.display = ''none'';',
'    }',
'  });',
'',
'  if (msgNenhum) {',
'    msgNenhum.style.display = algumVisivel ? ''none'' : ''block'';',
'  }',
'}',
'',
unistr('// Esconde cards asqualog se n\00E3o for ASQUALOG'),
'/*',
'if (!isAsqualog && !visivel) {',
'  document.querySelectorAll(''.asqualog'').forEach(card => {',
'    card.style.display = ''none'';',
'  });',
'}',
'*/',
'',
'document.addEventListener("DOMContentLoaded", () => {',
'  const btnOlho = document.querySelector(''.eye-button'');',
'  const icon = btnOlho?.querySelector(''i'');',
'  visivel = isAsqualog;',
'',
'  const inputBusca = document.querySelector(''.search-input'');',
'  if (inputBusca) {',
'    inputBusca.addEventListener(''input'', debounce(filtrarCards, 300));',
'  }',
'',
'  const botaoBusca = document.querySelector(''.search-button'');',
'  if (botaoBusca) {',
'    botaoBusca.addEventListener(''click'', filtrarCards);',
'  }',
'',
'  if (btnOlho && icon) {',
'    // Mostrar inicialmente os cards da ASQUALOG se permitido',
'    if (isAsqualog) {',
'      document.querySelectorAll(''.asqualog'').forEach(card => {',
'        card.style.display = ''flex'';',
'        card.style.filter = '''';',
'      });',
'    }',
'',
'    btnOlho.addEventListener(''click'', () => {',
'      visivel = !visivel;',
'',
unistr('      // Se for da ASQUALOG, s\00F3 troca o \00EDcone e t\00EDtulo'),
'      if (isAsqualog) {',
'        if (visivel) {',
'          icon.classList.remove(''fa-eye-slash'');',
'          icon.classList.add(''fa-eye'');',
'          btnOlho.title = ''Ocultar'';',
'        } else {',
'          icon.classList.remove(''fa-eye'');',
'          icon.classList.add(''fa-eye-slash'');',
unistr('          btnOlho.title = ''Visualizar todos os servi\00E7os'';'),
'        }',
unistr('        return; // N\00E3o executa mais nada'),
'      }',
'',
unistr('      // L\00F3gica para n\00E3o-ASQUALOG'),
'      if (visivel) {',
'        icon.classList.remove(''fa-eye-slash'');',
'        icon.classList.add(''fa-eye'');',
'        btnOlho.title = ''Ocultar'';',
'',
'        document.querySelectorAll(''.asqualog'').forEach(card => {',
'          card.style.display = ''flex'';',
'          aplicarEstiloCinza(card);',
'        });',
'      } else {',
'        icon.classList.remove(''fa-eye'');',
'        icon.classList.add(''fa-eye-slash'');',
unistr('        btnOlho.title = ''Visualizar todos os servi\00E7os'';'),
'',
'        document.querySelectorAll(''.asqualog'').forEach(card => {',
'          card.style.display = ''none'';',
'        });',
'      }',
'',
unistr('      filtrarCards(); // Atualiza a exibi\00E7\00E3o conforme o novo estado'),
'    });',
'  }',
'});',
''))
