unistr('-- Deleta as reservas que n\00E3o foram confirmadas pelos solicitantes.'),
'BEGIN',
'  DELETE FROM HORARIOS_MEZANINO',
'  WHERE ID_RESERVA IN (',
'      SELECT ID_RESERVA',
'      FROM RESERVAS',
'      WHERE DAT_CRIACAO < TRUNC(SYSDATE)',
'        AND PENDENTE = ''S''',
'  );',
'',
'  DELETE FROM TMP_RESERVAS',
'  WHERE DAT_CRIACAO < TRUNC(SYSDATE);',
'',
'  DELETE FROM ATENDIMENTO_RESERVAS',
'  WHERE FK_ATENDIMENTO_RESERVAS_RESERVAS IN (',
'      SELECT ID_RESERVA',
'      FROM RESERVAS',
'      WHERE PENDENTE = ''S''',
'        AND DAT_CRIACAO < TRUNC(SYSDATE)',
'  );',
'',
'  DELETE FROM RESERVAS',
'  WHERE DAT_CRIACAO < TRUNC(SYSDATE)',
'    AND PENDENTE = ''S'';',
'',
'  COMMIT;',
'END;',
''))
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
end;
