wwv_flow_imp_page.create_page(
 p_id=>3
,p_name=>'Fazer Reserva'
,p_alias=>'FAZER-RESERVA'
,p_step_title=>'Senado Federal'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('// Fun\00E7\00E3o para trocar o texto de ajuda conforme o tipo selecionado'),
'function atualizarTextoAjuda() {',
'',
'    var tipo = $v(''P3_TIP_RESERVAS'');',
'    var textoAjuda = '''';',
'',
'    // -------------------------',
'    // Porta-Banner',
'    // -------------------------',
'    if (tipo === ''Porta-Banner'') {',
'',
'        textoAjuda = `',
unistr('        Ap\00F3s finalizar este pedido de reserva, aguarde a confirma\00E7\00E3o da ASQUALOG por meio de notifica\00E7\00E3o via e-mail e acompanhando a Central de Servi\00E7os.<br><br>'),
'        ',
unistr('        Caso a ASQUALOG confirme a disponibilidade de data, quantidade e local de instala\00E7\00E3o, o demandante dever\00E1 seguir o fluxo estabelecido para produ\00E7\00E3o e aplica\00E7\00E3o dos materiais gr\00E1ficos nos Porta Banners.<br><br>'),
'',
unistr('        Esclarecemos que a ASQUALOG \00E9 respons\00E1vel pela gest\00E3o desses equipamentos, cujas especifica\00E7\00F5es s\00E3o as seguintes:<br><br>'),
'',
'        <strong>Porta Banner</strong><br>',
unistr('        \2022 Material: vidro com base de ferro<br>'),
unistr('        \2022 Dimens\00F5es: 1,20 m \00D7 1,40 m<br>'),
unistr('        \2022 Quantidade dispon\00EDvel: 8 unidades<br><br>'),
'',
unistr('        Refor\00E7amos que a instala\00E7\00E3o desses totens \00E9 realizada pelo setor de Patrim\00F4nio, ap\00F3s abertura da Ordem de Servi\00E7o pela ASQUALOG.<br><br>'),
unistr('        A produ\00E7\00E3o dos materiais gr\00E1ficos dever\00E1 ser solicitada pelo demandante ao SEGRAF, por meio de of\00EDcio contendo as informa\00E7\00F5es da campanha (nome, per\00EDodo), especifica\00E7\00F5es de tamanho conforme o tipo de totem e a arte a ser impressa.<br><br>'),
'        ',
unistr('        Por fim, a aplica\00E7\00E3o dos adesivos \00E9 de responsabilidade do SEACAB/SEGRAF, mediante agendamento pelo demandante. Ap\00F3s o t\00E9rmino da campanha, os totens ser\00E3o recolhidos pelo Patrim\00F4nio.'),
'        `;',
'',
'    // -------------------------',
'    // Porta-Cartaz',
'    // -------------------------',
'    } else if (tipo === ''Porta-Cartaz'') {',
'',
'        textoAjuda = `',
unistr('        Ap\00F3s finalizar este pedido de reserva, aguarde a confirma\00E7\00E3o da ASQUALOG por meio de notifica\00E7\00E3o via e-mail e acompanhando a Central de Servi\00E7os.<br><br>'),
'        ',
unistr('        Caso a ASQUALOG confirme a disponibilidade de data, quantidade e local de instala\00E7\00E3o, o demandante dever\00E1 seguir o fluxo estabelecido para produ\00E7\00E3o e aplica\00E7\00E3o dos materiais gr\00E1ficos nos Porta Cartazes.<br><br>'),
'',
unistr('        Esclarecemos que a ASQUALOG \00E9 respons\00E1vel pela gest\00E3o desses equipamentos, cujas especifica\00E7\00F5es s\00E3o as seguintes:<br><br>'),
'',
'        <strong>Porta Cartaz</strong><br>',
unistr('        \2022 Material: vidro com base de ferro<br>'),
unistr('        \2022 Dimens\00F5es:<br>'),
unistr('        &nbsp;&nbsp;\2013 0,55 m \00D7 1,42 m (estrutura sem base)<br>'),
unistr('        &nbsp;&nbsp;\2013 0,55 m \00D7 1,86 m (estrutura com base)<br>'),
unistr('        \2022 Quantidade dispon\00EDvel: 4 unidades<br><br>'),
'',
unistr('        Refor\00E7amos que a instala\00E7\00E3o desses totens \00E9 realizada pelo setor de Patrim\00F4nio, ap\00F3s abertura da Ordem de Servi\00E7o pela ASQUALOG.<br><br>'),
unistr('        A produ\00E7\00E3o dos materiais gr\00E1ficos dever\00E1 ser solicitada pelo demandante ao SEGRAF, por meio de of\00EDcio contendo as informa\00E7\00F5es da campanha (nome, per\00EDodo), especifica\00E7\00F5es de tamanho conforme o tipo de totem e a arte a ser impressa.<br><br>'),
'        ',
unistr('        Por fim, a aplica\00E7\00E3o dos adesivos \00E9 de responsabilidade do SEACAB/SEGRAF, mediante agendamento pelo demandante. Ap\00F3s o t\00E9rmino da campanha, os totens ser\00E3o recolhidos pelo Patrim\00F4nio.'),
'        `;',
'',
'    // -------------------------',
'    // Mezanino',
'    // -------------------------',
'    } else if (tipo === ''Mezanino'') {',
'',
'        textoAjuda = `',
unistr('            <span style="font-weight:bold;">O Mezanino n\00E3o pode ser reservado apenas por esse sistema!</span><br><br>'),
unistr('            Antes de solicitar a reserva, <span style="font-weight:bold;">verifique no calend\00E1rio</span> se j\00E1 existem reservas solicitadas para o mesmo per\00EDodo.<br><br>'),
unistr('            Caso seja vi\00E1vel o uso, <span style="font-weight:bold;">encaminhe um pedido via SIGAD \00E0 '),
unistr('            <span style="color:#b30000;">Primeira-Secretaria</span></span> solicitando a utiliza\00E7\00E3o do Mezanino.<br><br>'),
unistr('            Se a Primeira-Secretaria <span style="font-weight:bold;">autorizar</span>, ela enviar\00E1 um e-mail via SIGAD \00E0 '),
unistr('            <span style="font-weight:bold;">ASQUALOG</span> com as informa\00E7\00F5es da reserva.<br><br>'),
unistr('            A ASQUALOG, ent\00E3o, realizar\00E1 o cadastro da reserva em uma p\00E1gina espec\00EDfica para o Mezanino, '),
unistr('            <span style="font-weight:bold;">sem necessidade de nova an\00E1lise</span>.'),
'        `;',
'',
'    // -------------------------',
unistr('    // Espa\00E7o do Colaborador'),
'    // -------------------------',
'    } else {',
'',
'        textoAjuda = `',
unistr('            Ap\00F3s finalizar este pedido de reserva, aguarde a confirma\00E7\00E3o da ASQUALOG por meio de notifica\00E7\00E3o via e-mail e acompanhando a Central de Servi\00E7os.<br><br>'),
unistr('            <strong>Caso a ASQUALOG confirme a disponibilidade de data, o demandante dever\00E1 contatar a <span style="color:#b30000;">SEGRAF</span> para solicitar a produ\00E7\00E3o dos adesivos para as mesas do Espa\00E7o do Colaborador.</strong><br><br>'),
unistr('            Esclarecemos que o Espa\00E7o dos Colaboradores conta com 77 mesas no T\00E9rreo e 88 mesas no Mezanino, sendo que cada mesa possui as dimens\00F5es de 0,60m \00D7 0,80m.<br><br>'),
unistr('            Sugerimos que o adesivo n\00E3o cubra toda a superf\00EDcie da mesa e que a adesivagem seja feita de forma intercalada (em uma mesa sim, outra n\00E3o) para manter a harmonia visual do ambiente.'),
'        `;',
'    }',
'',
unistr('    // Aplica o conte\00FAdo no inline help'),
'    $(''#P3_TIP_RESERVAS_inline_help'').html(textoAjuda);',
'}',
'',
unistr('// Executa automaticamente ao carregar a p\00E1gina'),
'$(document).ready(function () {',
'    atualizarTextoAjuda();',
'});',
''))
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'$(''#P3_NUM_PARTICIPANTES'').on(''keypress'', function (e) {',
'  const charCode = e.which ? e.which : e.keyCode;',
unistr('  // Permite apenas n\00FAmeros (0 a 9)'),
'  if (charCode < 48 || charCode > 57) {',
'    e.preventDefault();',
'  }',
'});',
''))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
