,p_item_plug_id=>wwv_flow_imp.id(341994780833715878)
,p_item_source_plug_id=>wwv_flow_imp.id(341994780833715878)
,p_prompt=>'Local'
,p_source=>'LOC'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT rl.des_local  AS display_value,',
'       rl.des_local  AS return_value',
'FROM reservas_locais rl',
'WHERE :P3_TIP_RESERVAS IS NOT NULL',
'  AND (',
'        :P3_DAT_INICIO IS NULL',
'        OR :P3_DAT_FIM IS NULL',
'        OR NOT EXISTS (',
'              SELECT 1',
'              FROM reservas r',
'              WHERE r.tip_reservas = :P3_TIP_RESERVAS',
'                AND r.status <> ''Cancelado''',
'                AND TRIM(UPPER(r.loc)) = TRIM(UPPER(rl.des_local))',
'                AND r.dat_inicio <= :P3_DAT_FIM',
'                AND r.dat_fim    >= :P3_DAT_INICIO',
'          )',
'      )',
unistr('  -- remove os j\00E1 escolhidos'),
'  AND (',
'        :P3_LOC IS NULL',
'        OR INSTR('':'' || :P3_LOC || '':'', '':'' || rl.des_local || '':'') = 0',
'      )',
'ORDER BY rl.des_local;',
''))
,p_lov_cascade_parent_items=>'P3_TIP_RESERVAS,P3_DAT_INICIO,P3_DAT_FIM'
,p_ajax_items_to_submit=>'P3_TIP_RESERVAS,P3_DAT_INICIO,P3_DAT_FIM,P3_LOC'
