wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(120462634507522833)
,p_event_id=>wwv_flow_imp.id(120462552055522832)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_locais    VARCHAR2(1000);',
'BEGIN',
'    SELECT LISTAGG(r.des_local, '':'') WITHIN GROUP (ORDER BY r.des_local) INTO v_locais',
'    FROM reservas_locais r',
'    WHERE :P3_TIP_RESERVAS IS NOT NULL',
'      AND (',
'            :P3_DAT_INICIO IS NULL',
'            OR :P3_DAT_FIM IS NULL',
'            OR NOT EXISTS (',
'                  SELECT 1',
'                  FROM reservas r',
'                  WHERE r.tip_reservas = :P3_TIP_RESERVAS',
'                    AND r.status <> ''Cancelado''',
'                    AND TRIM(UPPER(r.loc)) = TRIM(UPPER(r.des_local))',
'                    AND r.dat_inicio <= :P3_DAT_FIM',
'                    AND r.dat_fim    >= :P3_DAT_INICIO',
'              )',
'          )',
unistr('      -- remove os j\00E1 escolhidos'),
'      AND (',
'            :P3_LOC IS NULL',
'            OR INSTR('':'' || :P3_LOC || '':'', '':'' || r.des_local || '':'') = 0',
'          )',
'    ORDER BY r.des_local;',
'',
'    :P3_LOC := v_locais;',
'END;'))
,p_attribute_02=>'P3_TIP_RESERVAS,P3_DAT_INICIO,P3_DAT_FIM,P3_LOC'
,p_attribute_03=>'P3_LOC'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
