'       max(r.num_participantes),',
'       LISTAGG(''- '' || LOC, ''<br>'')',
'            WITHIN GROUP (ORDER BY LOC) AS LOCAIS,',
'       max(r.OBS)',
'FROM RESERVAS r',
'WHERE r.pendente = ''S''',
'  AND r.tip_reservas <> ''Mezanino''',
'  AND LPAD(r.COD_PESSOA, 11, ''0'') = ',
'      CASE',
'          WHEN REGEXP_LIKE(:APP_USER, ''^\d+$'')',
