wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(233572591008130086)
,p_process_sequence=>20
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Cancelar Reservas e mandar email'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_email_remetente   VARCHAR2(200) := ''asqualog@senado.leg.br'';',
'    v_email_destino     VARCHAR2(200) := ''sequalog-equipe@senado.gov.br'';',
'    v_assunto           VARCHAR2(200) := ''Cancelamento de reservas'';',
'    v_mensagem          CLOB := '''';',
'    v_bloco             CLOB := '''';',
'',
'    v_count             NUMBER;',
'BEGIN',
'    SELECT COUNT(*) INTO v_count',
'    FROM reservas',
'    WHERE ind_delete = ''S''',
'        AND LPAD(cod_pessoa, 11, ''0'') = :P5_CPF;',
'    ',
'    IF v_count = 0 THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20020,',
'            ''Selecione alguma reserva para deletar''',
'        );',
'    END IF;',
'',
'    v_mensagem := ',
'        ''<p>Prezados,</p>'' ||',
'        ''<p>Informamos que foram solicitados cancelamentos para as seguintes reservas:</p>'';',
'',
'    FOR rec IN (',
'        SELECT ',
'            r.titulo_reserva,',
'            r.des_reserva,',
'            r.tip_reservas,',
'            MAX(r.num_participantes) num_participantes,',
'            TO_CHAR(r.dat_inicio, ''DD/MM/YYYY'') data_inicio,',
'            TO_CHAR(r.dat_fim, ''DD/MM/YYYY'') data_fim,',
'            MAX(v.nom_pessoa) as solicitante,',
'            LISTAGG(''- '' || NVL(r.loc, ''N/A''), ''<br>'')',
'                WITHIN GROUP (ORDER BY r.loc) locais',
'        FROM reservas r',
'        LEFT JOIN dda.vinculo_sf v',
'            ON v.num_cpf = LPAD(r.cod_pessoa, 11, ''0'')',
'            AND v.ind_vinculo_ativo = ''S''',
'        WHERE r.ind_delete = ''S''',
'            AND LPAD(TO_CHAR(r.cod_pessoa), 11, ''0'') = :P5_CPF',
'        GROUP BY',
'            r.titulo_reserva,',
'            r.des_reserva,',
'            r.tip_reservas,',
'            r.dat_inicio,',
'            r.dat_fim',
'        ORDER BY r.dat_inicio, r.titulo_reserva',
'    ) LOOP',
'        v_bloco :=',
'            ''<hr>'' ||',
'            ''<strong>Nome do Evento:</strong> '' || rec.titulo_reserva || ''<br>'' ||',
unistr('            ''<strong>Descri\00E7\00E3o:</strong> '' || rec.des_reserva || ''<br>'' ||'),
'            ''<strong>Tipo:</strong> '' || rec.tip_reservas || ''<br>'' ||',
unistr('            ''<strong>Per\00EDodo:</strong> '' || rec.data_inicio || '' at\00E9 '' || rec.data_fim || ''<br>'' ||'),
'            ''<strong>Estimativa de Pessoas:</strong> '' ||',
'                NVL(TO_CHAR(rec.num_participantes),''---'') || ''<br>'' ||',
unistr('            ''<strong>Solicitante:</strong> '' || NVL(rec.solicitante,''N\00E3o identificado'') || ''<br><br>'' ||'),
'',
'            ''<strong>Locais:</strong><br>'' ||',
'            NVL(rec.locais, ''- Nenhum'') || ''<br>'';',
'',
'        v_mensagem := v_mensagem || v_bloco;',
'    END LOOP;',
'',
'    v_mensagem := v_mensagem ||',
unistr('        ''<p>Favor adotar as provid\00EAncias necess\00E1rias.</p>'' ||'),
'        ''Atenciosamente,<br><br>'' ||',
'        ''<b>Sistema RTMES</b><br>'' ||',
unistr('        ''Reservas de Totens e Mesas - Espa\00E7o do Servidor<br>'';'),
'',
'    APEX_MAIL.SEND(',
'        p_to        => v_email_destino,',
'        p_from      => v_email_remetente,',
'        p_subj      => v_assunto,',
'        p_body      => NULL,',
'        p_body_html => v_mensagem',
'    );',
'',
'    APEX_MAIL.PUSH_QUEUE;',
'',
'    UPDATE reservas',
'    SET ind_delete = ''N'',',
'        status = ''Cancelado''',
'    WHERE ind_delete = ''S''',
'        AND LPAD(TO_CHAR(cod_pessoa), 11, ''0'') = :P5_CPF;',
'',
'    COMMIT;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(233572258458130082)
,p_internal_uid=>115605518752825537
);
end;
