begin
wwv_flow_imp_page.create_page(
 p_id=>11
,p_name=>unistr('Confirma\00E7\00E3o Asqualog')
,p_alias=>unistr('CONFIRMA\00C7\00C3O-ASQUALOG')
,p_step_title=>'Senado Federal'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('// Fun\00E7\00E3o para fazer o acorde\00E3o funcionar, abrindo e fechando'),
unistr('// Fun\00E7\00E3o para fazer o acorde\00E3o funcionar, abrindo e fechando'),
'function toggleRegion(regionId) {',
'    const region = document.getElementById(regionId);',
'    const icon = document.getElementById(''icon_'' + regionId);',
'    const buttonEmail = document.getElementById(''btn_'' + regionId);',
'    const buttonOS = document.getElementById(''btn_os_'' + regionId);',
'    const buttonConf = document.getElementById(''btn_confirmar_'' + regionId);',
'        ',
'    if (region.style.display === ''none'') {',
'        region.style.display = ''block'';',
'        icon.classList.remove(''fa-chevron-down'');',
'        icon.classList.add(''fa-chevron-up'');',
'        ',
'        if (buttonEmail) buttonEmail.style.display = ''inline-block'';',
'        if (buttonOS) buttonOS.style.display = ''inline-block'';',
'        if (buttonConf) buttonConf.style.display = ''inline-block'';',
'        ',
'        if (!region.dataset.loaded) {',
'            const grupoId = regionId.replace(''grupo_'', '''');',
'',
unistr('            // Utiliza do processo dessa p\00E1gina passando o id do grupo'),
'            apex.server.process(''LOAD_REPORT_BY_GROUP'', {',
'                x01: grupoId',
'            }, {',
unistr('                // Se der certo, retorna o relat\00F3rio do grupo e marca true para que n\00E3o recarregar no futuro'),
'                success: function(data) {',
'                    const targetDiv = document.getElementById(''relatorio_'' + grupoId);',
'                    if (targetDiv) {',
'                        targetDiv.innerHTML = data.html;',
'                        region.dataset.loaded = "true";',
'                    }',
'                },',
'                error: function(jqXHR, textStatus, errorThrown) {',
unistr('                    console.error("Erro ao carregar o relat\00F3rio:", textStatus, errorThrown);'),
'                }',
'            });',
'        }',
'    } else {',
'        region.style.display = ''none'';',
'        icon.classList.remove(''fa-chevron-up'');',
'        icon.classList.add(''fa-chevron-down'');',
'        ',
'        if (buttonEmail) buttonEmail.style.display = ''none'';',
'        if (buttonOS) buttonOS.style.display = ''none'';',
'        if (buttonConf) buttonConf.style.display = ''none'';',
'    }',
'}',
'',
'',
unistr('// Carrega os relat\00F3rios de cada grupo de reserva'),
'function loadReport(regionId) {',
'    const grupo = regionId.replace(''grupo_'', '''').replace(/_/g, '' '');    // Pega o id do grupo',
'    ',
unistr('    // Fazer chamada AJAX para carregar o relat\00F3rio'),
'    apex.server.process(''LOAD_REPORT_BY_GROUP'', {',
'        x01: grupo',
'    }, {',
'        success: function(data) {',
'            document.getElementById(''relatorio_'' + regionId.replace(''grupo_'', '''')).innerHTML = data.html;',
'            document.getElementById(regionId).setAttribute(''data-loaded'', ''true'');',
'        }',
'    });',
'}'))
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'(function abrirGrupoAtivo() {',
'  var grupoId = $v("P11_ID_GRUPO_ATIVO");',
'  if (!grupoId) return;',
'',
'  var todosGrupos = document.querySelectorAll("[id^=''grupo_'']");',
'  var todosIcones = document.querySelectorAll("[id^=''icon_grupo_'']");',
'  var todosBotoes = document.querySelectorAll("[id^=''btn_grupo_'']");',
'  var todosBotoesOS = document.querySelectorAll("[id^=''btn_os_grupo_'']");',
'  var todosBotoesConf = document.querySelectorAll("[id^=''btn_confirmar_grupo_''");',
'',
'  // Esconde todos os grupos',
'  todosGrupos.forEach(g => g.style.display = ''none'');',
'',
'  todosIcones.forEach(i => {',
'    i.classList.remove("fa-chevron-up");',
'    i.classList.add("fa-chevron-down");',
'  });',
'',
'  todosBotoes.forEach(b => b.style.display = ''none'');',
'  todosBotoesOS.forEach(b => b.style.display = ''none''); ',
'  todosBotoesConf.forEach(b => b.style.display = ''none'');',
'',
'  var regionId = ''grupo_'' + grupoId;',
'  var icon = document.getElementById("icon_" + regionId);',
'  var grupo = document.getElementById(regionId);',
'  var botao = document.getElementById("btn_" + regionId);',
'  var botaoOS = document.getElementById("btn_os_" + regionId);',
'  var botaoConf = document.getElementById("btn_confirmar_" + regionId);',
'',
'  if (grupo) {',
'    grupo.style.display = ''block'';',
'    grupo.dataset.loaded = grupo.dataset.loaded || "false";',
'',
'    if (botao) botao.style.display = ''inline-block'';',
'    if (botaoOS) botaoOS.style.display = ''inline-block'';',
'    if (botaoConf) botaoConf.style.display = ''inline-block'';',
'',
'    if (icon) {',
'      icon.classList.remove("fa-chevron-down");',
'      icon.classList.add("fa-chevron-up");',
'    }',
'',
unistr('    // Se ainda n\00E3o foi carregado, chama o processo para popular'),
'    if (grupo.dataset.loaded === "false") {',
'      apex.server.process(''LOAD_REPORT_BY_GROUP'', {',
'        x01: grupoId',
'      }, {',
'        success: function(data) {',
'          var targetDiv = document.getElementById(''relatorio_'' + grupoId);',
'          if (targetDiv) {',
'            targetDiv.innerHTML = data.html;',
'            grupo.dataset.loaded = "true";',
'          }',
'        },',
'        error: function(jqXHR, textStatus, errorThrown) {',
unistr('          console.error("Erro ao carregar o relat\00F3rio:", textStatus, errorThrown);'),
'        }',
'      });',
'    }',
'  }',
'})();',
''))
