wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(343740462680528054)
,p_plug_name=>unistr('Calend\00E1rio')
,p_parent_plug_id=>wwv_flow_imp.id(343740315329528053)
,p_region_css_classes=>'calendario'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_escape_on_http_output=>'Y'
,p_plug_template=>wwv_flow_imp.id(341738481904707171)
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ID_RESERVA,',
'       DAT_INICIO,',
'       DAT_FIM,',
'       TIP_RESERVAS,',
'       STATUS,',
'       NUM_PARTICIPANTES,',
'       TITULO_RESERVA,',
'       DES_RESERVA,',
'       COD_PESSOA,',
'       PENDENTE,',
'       LOC,',
'       JUSTIFICATIVA,',
'       OBS,',
'       dbms_lob.getlength(ARQ) as foto,',
'       MIMETYPE,',
'       FILENAME,',
'       CASE ',
'            WHEN TITULO_RESERVA IS NOT NULL AND LOC IS NOT NULL THEN ',
'                tip_reservas || '' - '' || TITULO_RESERVA || '' - '' || LOC',
'            WHEN TITULO_RESERVA IS NOT NULL AND LOC IS NULL THEN ',
'                tip_reservas || '' - '' || TITULO_RESERVA',
'       END AS exibir,',
'       CASE ',
'            WHEN tip_reservas = ''Adesivagem'' THEN ''adesivagem''',
'            WHEN tip_reservas = ''Mezanino'' THEN ''mezanino''',
'            WHEN tip_reservas = ''Porta-Banner'' THEN ''porta-banner''',
'            WHEN tip_reservas = ''Porta-Cartaz'' THEN ''porta-cartaz''',
'       END AS css_class',
'FROM RESERVAS r',
'JOIN (',
'    SELECT num_cpf,',
'           MAX(sgl_orgao_exercicio) KEEP (DENSE_RANK LAST ORDER BY dat_inicio_vinculo) ',
'             AS sgl_orgao_exercicio',
'    FROM dda.vinculo_sf',
'    WHERE ind_vinculo_ativo = ''S''',
'    GROUP BY num_cpf',
') v',
'   ON v.num_cpf = LPAD(r.cod_pessoa, 11, ''0'')',
'WHERE status IN (''Confirmado'', ''Realizado'')',
'  AND (:P11_FILTRO IS NULL OR tip_reservas = :P11_FILTRO)',
'  AND (:P11_INICIO IS NULL OR dat_inicio >= :P11_INICIO)',
'  AND (:P11_FIM IS NULL OR dat_inicio <= :P11_FIM)',
'  AND (',
'        :P11_TITULO IS NULL OR ',
'        REGEXP_LIKE(UPPER(titulo_reserva), ''(^| )'' || UPPER(:P11_TITULO))',
'      )',
'  AND (',
'        :P11_SETOR IS NULL OR ',
'        v.sgl_orgao_exercicio IN (',
'            SELECT TRIM(COLUMN_VALUE)',
'            FROM TABLE(apex_string.split(:P11_SETOR, '':''))',
'        )',
'      )',
''))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CSS_CALENDAR'
,p_ajax_items_to_submit=>'P11_FILTRO,P11_INICIO,P11_FIM,P11_TITULO,P11_SETOR'
,p_attribute_01=>'DAT_INICIO'
,p_attribute_02=>'DAT_FIM'
,p_attribute_03=>'EXIBIR'
,p_attribute_04=>'ID_RESERVA'
,p_attribute_05=>'f?p=&APP_ID.:204:&SESSION.::&DEBUG.:204:P204_ID_RESERVA:&ID_RESERVA.'
,p_attribute_07=>'N'
,p_attribute_09=>'list:navigation'
,p_attribute_13=>'N'
,p_attribute_14=>'CSS_CLASS'
,p_attribute_16=>'&TIPO.'
,p_attribute_17=>'Y'
,p_attribute_19=>'Y'
,p_attribute_21=>'10'
,p_attribute_22=>'Y'
);
