wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(343740574679528055)
,p_plug_name=>'Reservas Confirmadas'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(341728690632707168)
,p_plug_display_sequence=>60
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DAT_INICIO,',
'       DAT_FIM,',
'       TIP_RESERVAS,',
'       STATUS,',
'       max(NUM_PARTICIPANTES),',
'       TITULO_RESERVA,',
'       DES_RESERVA,',
'       max(COD_PESSOA),',
'       LISTAGG(''- '' || LOC, ''<br>'')',
'            WITHIN GROUP (ORDER BY LOC) AS LOCAIS,',
'       max(JUSTIFICATIVA),',
'       max(OBS),',
'       max(OBS_ASQUALOG),',
'       CASE ',
'            WHEN tip_reservas = ''Adesivagem'' THEN ''adesivagem''',
'            WHEN tip_reservas = ''Mezanino'' THEN ''mezanino''',
'            WHEN tip_reservas = ''Porta-Banner'' THEN ''porta-banner''',
'            WHEN tip_reservas = ''Porta-Cartaz'' THEN ''porta-cartaz''',
'       END AS css_class,',
'       max(v.nom_pessoa),',
'       max(v.sgl_orgao_exercicio)',
'FROM RESERVAS r',
'JOIN (',
'    SELECT num_cpf,',
'           MAX(nom_pessoa) AS nom_pessoa,',
'           MAX(sgl_orgao_exercicio) KEEP (DENSE_RANK LAST ORDER BY dat_inicio_vinculo) ',
'             AS sgl_orgao_exercicio',
'    FROM dda.vinculo_sf',
'    WHERE ind_vinculo_ativo = ''S''',
'    GROUP BY num_cpf',
') v',
'   ON v.num_cpf = LPAD(r.cod_pessoa, 11, ''0'')',
'WHERE status IN (''Confirmado'', ''Realizado'')',
'  AND (:P11_FILTRO IS NULL OR tip_reservas = :P11_FILTRO)',
'  AND (:P11_INICIO IS NULL OR dat_inicio >= :P11_INICIO)',
'  AND (:P11_FIM IS NULL OR dat_inicio <= :P11_FIM)',
'  AND (',
'        :P11_TITULO IS NULL OR ',
'        REGEXP_LIKE(UPPER(titulo_reserva), ''(^| )'' || UPPER(:P11_TITULO))',
'      )',
'  AND (',
'        :P11_SETOR IS NULL OR ',
'        v.sgl_orgao_exercicio IN (',
'            SELECT TRIM(COLUMN_VALUE)',
'            FROM TABLE(apex_string.split(:P11_SETOR, '':''))',
'        )',
'      )',
'GROUP BY',
'    titulo_reserva,',
'    des_reserva,',
'    tip_reservas,',
'    dat_inicio,',
'    dat_fim,',
'    status',
'ORDER BY r.dat_inicio desc, r.tip_reservas',
''))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P11_FILTRO,P11_INICIO,P11_FIM,P11_TITULO,P11_SETOR'
