,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('// Atualiza apenas a regi\00E3o da reserva avaliada e faz o refresh da p\00E1gina, colapsando o grupo da reserva'),
'',
'var idGrupo = this.data.idGrupo;',
'',
'if (idGrupo) {',
unistr('  // Atualiza apenas a regi\00E3o espec\00EDfica do grupo'),
'  var regiaoId = "grupo_" + idGrupo;',
'',
unistr('  // Faz o refresh da regi\00E3o espec\00EDfica'),
'  var regiao = apex.region(regiaoId);',
'  if (regiao) {',
'    regiao.refresh();',
'',
unistr('    // Se quiser colapsar visualmente ap\00F3s atualizar'),
'    setTimeout(function() {',
'      $("[data-id-grupo=''" + idGrupo + "'']").addClass("is-collapsed");',
'    }, 500); // tempo suficiente pro refresh completar',
'  } else {',
unistr('    console.warn("Regi\00E3o n\00E3o encontrada:", regiaoId);'),
'  }',
'}',
''))
);
