wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(367408989105832962)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'LOAD_REPORT_BY_GROUP'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_grupo      NUMBER := TO_NUMBER(APEX_APPLICATION.G_X01);',
'    l_html       CLOB;',
'    l_url        CLOB;',
'    l_imagem_url CLOB;',
'BEGIN',
'    l_html := q''[',
'<div class="t-Report t-Report--altRowsDefault">',
'  <div class="t-Report-wrap">',
'    <table class="t-Report-report tabela-reservas">',
'      <thead>',
'        <tr>',
'          <th>Analisar</th>',
'          <th>Status</th>',
'          <th>ID</th>',
'          <th>Local</th>',
'          <th>Nome da Reserva</th>',
unistr('          <th>Descri\00E7\00E3o</th>'),
'          <th>Tipo</th>',
unistr('          <th>In\00EDcio</th>'),
'          <th>Fim</th>',
'          <th>Estimativa (Pessoas)</th>',
unistr('          <th>Observa\00E7\00E3o</th>'),
'          <th>Solicitante</th>',
unistr('          <th>\00D3rg\00E3o</th>'),
'          <th>Arquivo</th>',
'        </tr>',
'      </thead>',
'      <tbody>',
']'';',
'',
'    FOR rec IN (',
'        SELECT',
'            r.id_reserva,',
'            r.titulo_reserva,',
'            r.des_reserva,',
'            r.obs,',
'            r.dat_inicio,',
'            r.dat_fim,',
'            r.tip_reservas,',
'            r.loc,',
'            r.num_participantes,',
'            r.status,',
'            v.nom_pessoa,',
'            o.sgl_orgao || '' - '' || o.nom_orgao || '' ('' || o.sgl_orgao_hierarquia || '')'' AS orgao_formatado,',
'            NVL(DBMS_LOB.getlength(r.arq), 0) AS foto_tamanho,',
'',
'            COUNT(*) OVER (',
'                PARTITION BY',
'                    r.titulo_reserva,',
'                    r.des_reserva,',
'                    r.tip_reservas,',
'                    r.dat_inicio,',
'                    r.dat_fim,',
'                    r.num_participantes,',
'                    r.obs,',
'                    r.cod_pessoa',
'            ) AS qtd_linhas_grupo,',
'',
'            ROW_NUMBER() OVER (',
'                PARTITION BY',
'                    r.titulo_reserva,',
'                    r.des_reserva,',
'                    r.tip_reservas,',
'                    r.dat_inicio,',
'                    r.dat_fim,',
'                    r.num_participantes,',
'                    r.obs,',
'                    r.cod_pessoa',
'                ORDER BY r.id_reserva',
'            ) AS rn_grupo',
'        FROM reservas r',
'        JOIN dda.vinculo_sf v',
'            ON v.num_cpf = LPAD(TO_CHAR(r.cod_pessoa), 11, ''0'')',
'        JOIN dda.orgao o',
'            ON o.sgl_orgao = v.sgl_orgao_exercicio',
'        JOIN (',
'            SELECT fk_atendimento_reservas_reservas',
'            FROM (',
'                SELECT a.fk_atendimento_reservas_reservas,',
'                       ROW_NUMBER() OVER (',
'                           PARTITION BY a.fk_atendimento_reservas_reservas',
'                           ORDER BY a.dat_criacao_atendimento DESC, a.pk_atendimento_reservas DESC',
'                       ) rn',
'                FROM atendimento_reservas a',
'            )',
'            WHERE rn = 1',
'        ) ult ON ult.fk_atendimento_reservas_reservas = r.id_reserva',
'        WHERE r.cod_grupo_reserva = l_grupo',
'          AND v.ind_vinculo_ativo = ''S''',
'        ORDER BY',
'            r.titulo_reserva,',
'            r.des_reserva,',
'            r.tip_reservas,',
'            r.dat_inicio,',
'            r.id_reserva',
'    ) LOOP',
'',
'        l_url := apex_util.prepare_url(',
'            ''f?p='' || :APP_ID || '':201:'' || :APP_SESSION ||',
'            ''::NO::P201_ID_RESERVA,P201_COD_GRUPO_RESERVA:'' ||',
'            rec.id_reserva || '','' || l_grupo',
'        );',
'',
'        l_imagem_url := apex_util.prepare_url(',
'            ''f?p='' || :APP_ID || '':203:'' || :APP_SESSION ||',
'            ''::NO::P203_ID_RESERVA:'' || rec.id_reserva',
'        );',
'',
'        l_html := l_html || ''<tr>'';',
'',
'        -- Analisar',
'        l_html := l_html || ''<td class="col-analisar">'' ||',
'            ''<a href="'' || l_url || ''" '' ||',
'            ''class="t-Button t-Button--noLabel t-Button--icon t-Button--small" '' ||',
'            ''title="Ver Detalhes">'' ||',
'            ''<span class="fa fa-eye" aria-hidden="true"></span></a></td>'';',
'',
'        -- Status',
'        DECLARE',
'            l_check_opacity VARCHAR2(20);',
'            l_x_opacity     VARCHAR2(20);',
'        BEGIN',
'            -- Define opacidades com base no status',
'            IF rec.status = ''Confirmado'' THEN',
'                l_check_opacity := ''opacity:1;'';',
'                l_x_opacity     := ''opacity:0.2;'';',
'            ELSIF rec.status = ''Cancelado'' THEN',
'                l_check_opacity := ''opacity:0.2;'';',
'                l_x_opacity     := ''opacity:1;'';',
'            ELSE',
'                l_check_opacity := ''opacity:0.2;'';',
'                l_x_opacity     := ''opacity:0.2;'';',
'            END IF;',
'',
'            l_html := l_html || ',
'                ''<td class="col-status">'' ||',
unistr('                    -- Coluna com \00EDcones de a\00E7\00E3o (check e X)'),
'                    ''<span class="fa fa-check" style="margin-right:8px; background-color:#28a745; border-color:#28a745; color:white;'' || l_check_opacity || ''" title="Confirmar"></span>'' ||',
'                    ''<span class="fa fa-times" style="background-color:#dc3545; border-color:#dc3545; color:white;'' || l_x_opacity || ''" title="Cancelar"></span>'' ||',
'                ''</td>'';',
'        END;',
'',
unistr('        -- ID e Local (n\00E3o mesclados)'),
'        l_html := l_html || ''<td class="col-id">'' || rec.id_reserva || ''</td>'';',
'        l_html := l_html || ''<td class="col-local">'' || NVL(APEX_ESCAPE.HTML(rec.loc), ''Sem Local'') || ''</td>'';',
'',
unistr('        -- Campos mesclados (somente na 1\00AA linha do grupo)'),
'        IF rec.rn_grupo = 1 THEN',
'            l_html := l_html ||',
'                ''<td class="col-name" rowspan="'' || rec.qtd_linhas_grupo || ''">'' || APEX_ESCAPE.HTML(rec.titulo_reserva) || ''</td>'' ||',
'                ''<td class="col-desc" rowspan="'' || rec.qtd_linhas_grupo || ''">'' || APEX_ESCAPE.HTML(rec.des_reserva) || ''</td>'' ||',
'                ''<td rowspan="'' || rec.qtd_linhas_grupo || ''">'' || APEX_ESCAPE.HTML(rec.tip_reservas) || ''</td>'' ||',
'                ''<td rowspan="'' || rec.qtd_linhas_grupo || ''">'' || TO_CHAR(rec.dat_inicio, ''DD/MM/YYYY'') || ''</td>'' ||',
'                ''<td rowspan="'' || rec.qtd_linhas_grupo || ''">'' || TO_CHAR(rec.dat_fim, ''DD/MM/YYYY'') || ''</td>'' ||',
'                ''<td rowspan="'' || rec.qtd_linhas_grupo || ''">'' ||',
'                    NVL(TO_CHAR(rec.num_participantes), ''Sem Estimativa'') || ''</td>'' ||',
'                ''<td rowspan="'' || rec.qtd_linhas_grupo || ''">'' ||',
unistr('                    NVL(APEX_ESCAPE.HTML(rec.obs), ''N\00E3o h\00E1.'') || ''</td>'' ||'),
'                ''<td rowspan="'' || rec.qtd_linhas_grupo || ''">'' ||',
'                    APEX_ESCAPE.HTML(rec.nom_pessoa) || ''</td>'' ||',
'                ''<td class="col-orgao" rowspan="'' || rec.qtd_linhas_grupo || ''">'' ||',
'                    APEX_ESCAPE.HTML(rec.orgao_formatado) || ''</td>'';',
'                    ',
'            IF rec.foto_tamanho > 0 THEN',
'                l_html := l_html ||',
'                    ''<td class="col-arquivo" rowspan="'' || rec.qtd_linhas_grupo || ''">'' ||',
'                        ''<a href="'' || l_imagem_url || ''" title="Baixar">'' ||',
'                            ''<span class="fa fa-download"></span>'' ||',
'                        ''</a>'' ||',
'                    ''</td>'';',
'            ELSE',
'                l_html := l_html ||',
unistr('                    ''<td class="col-arquivo" rowspan="'' || rec.qtd_linhas_grupo || ''">N\00E3o h\00E1.</td>'';'),
'            END IF;',
'        END IF;',
'        l_html := l_html || ''</tr>'';',
'    END LOOP;',
'',
'    l_html := l_html || q''[</tbody></table></div></div>]'';',
'',
'    APEX_JSON.OPEN_OBJECT;',
'    APEX_JSON.WRITE(''html'', l_html);',
'    APEX_JSON.CLOSE_OBJECT;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>166635996867734017
);
