,p_plug_new_grid_row=>false
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'FUNC_BODY_RETURNING_SQL'
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_sql   CLOB;',
'    v_tipos VARCHAR2(4000);',
'    v_meses VARCHAR2(4000);',
'    v_setor VARCHAR2(4000);',
'BEGIN',
'    IF :P12_FILTRO_TIPO IS NOT NULL THEN',
'        v_tipos := '''''''' || REPLACE(:P12_FILTRO_TIPO, '':'', '''''','''''') || '''''''';',
'    END IF;',
'',
'    IF :P12_FILTRO_MES IS NOT NULL THEN',
'        v_meses := '''''''' || REPLACE(:P12_FILTRO_MES, '':'', '''''','''''') || '''''''';',
'    END IF;',
'',
'    IF :P12_FILTRO_SETOR IS NOT NULL THEN',
'        v_setor := '''''''' || REPLACE(:P12_FILTRO_SETOR, '':'', '''''','''''') || '''''''';',
'    END IF;',
'',
'    v_sql := ''',
'        SELECT ',
'            NVL(',
'                ROUND(',
'                    COUNT(*) / NULLIF(COUNT(DISTINCT TRUNC(R.DAT_INICIO)), 0),',
'                    2',
'                ),',
'                0',
'            ) AS MEDIA_RESERVAS_DIA',
'        FROM RESERVAS R',
'        JOIN DDA.VINCULO_SF V',
'          ON LPAD(R.cod_pessoa, 11, ''''0'''') = V.num_cpf',
'        WHERE 1=1',
'            AND R.PENDENTE = ''''N'''' '';',
'',
'    IF v_tipos IS NOT NULL THEN',
'        v_sql := v_sql || '' AND R.TIP_RESERVAS IN ('' || v_tipos || '')'';',
'    END IF;',
'',
'    IF v_meses IS NOT NULL THEN',
'        v_sql := v_sql || '' AND TO_CHAR(R.DAT_INICIO, ''''MM/YYYY'''') IN ('' || v_meses || '')'';',
'    END IF;',
'',
'    IF v_setor IS NOT NULL THEN',
'        v_sql := v_sql || '' AND V.SGL_ORGAO_EXERCICIO IN ('' || v_setor || '')'';',
'    END IF;',
'',
'    RETURN v_sql;',
'END;',
''))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_ajax_items_to_submit=>'P12_FILTRO_TIPO,P12_FILTRO_MES,P12_FILTRO_SETOR'
