,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH DIAS AS (',
'   SELECT 1 AS ORDEM, ''SEGUNDA-FEIRA'' AS DIA_SEMANA FROM DUAL UNION ALL',
unistr('   SELECT 2, ''TER\00C7A-FEIRA''   FROM DUAL UNION ALL'),
'   SELECT 3, ''QUARTA-FEIRA''  FROM DUAL UNION ALL',
'   SELECT 4, ''QUINTA-FEIRA''  FROM DUAL UNION ALL',
'   SELECT 5, ''SEXTA-FEIRA''   FROM DUAL UNION ALL',
unistr('   SELECT 6, ''S\00C1BADO''        FROM DUAL UNION ALL'),
'   SELECT 7, ''DOMINGO''       FROM DUAL',
'),',
'BASE AS (',
'   SELECT ',
'       TO_NUMBER(TO_CHAR(r.DAT_CRIACAO, ''D'')) AS ORDEM,',
'       r.TIP_RESERVAS',
'   FROM RESERVAS r',
'   WHERE EXISTS (',
'       SELECT 1',
'       FROM ATENDIMENTO_RESERVAS ar',
'       WHERE ar.FK_ATENDIMENTO_RESERVAS_RESERVAS = r.ID_RESERVA',
'   )',
'   AND (',
'       :P12_FILTRO_TIPO IS NULL',
'       OR r.TIP_RESERVAS IN (',
'           SELECT REGEXP_SUBSTR(:P12_FILTRO_TIPO, ''[^:]+'', 1, LEVEL)',
'           FROM dual',
'           CONNECT BY LEVEL <= REGEXP_COUNT(:P12_FILTRO_TIPO, '':'') + 1',
'       )',
'   )',
'   AND (',
'       :P12_FILTRO_SETOR IS NULL',
'       OR EXISTS (',
'           SELECT 1',
'           FROM dda.vinculo_sf vs',
'           WHERE LPAD(r.cod_pessoa, 11, ''0'') = vs.num_cpf',
'           AND vs.sgl_orgao_exercicio IN (',
'               SELECT REGEXP_SUBSTR(:P12_FILTRO_SETOR, ''[^:]+'', 1, LEVEL)',
'               FROM dual',
'               CONNECT BY LEVEL <= REGEXP_COUNT(:P12_FILTRO_SETOR, '':'') + 1',
'           )',
'       )',
'   )',
'   AND (',
'       :P12_FILTRO_MES IS NULL',
'       OR TO_CHAR(r.dat_criacao, ''MM/YYYY'') IN (',
'           SELECT REGEXP_SUBSTR(:P12_FILTRO_MES, ''[^:]+'', 1, LEVEL)',
'           FROM dual',
'           CONNECT BY LEVEL <= REGEXP_COUNT(:P12_FILTRO_MES, '':'') + 1',
'       )',
'   )',
'   AND TRUNC(r.DAT_CRIACAO, ''MM'') = TRUNC(SYSDATE, ''MM'')',
')',
'SELECT ',
'    d.DIA_SEMANA,',
'    d.ORDEM,',
'    NVL(SUM(CASE WHEN b.TIP_RESERVAS = ''Adesivagem''   THEN 1 ELSE 0 END), 0) AS Adesivagem,',
'    NVL(SUM(CASE WHEN b.TIP_RESERVAS = ''Porta-Cartaz'' THEN 1 ELSE 0 END), 0) AS Porta_Cartaz,',
'    NVL(SUM(CASE WHEN b.TIP_RESERVAS = ''Porta-Banner'' THEN 1 ELSE 0 END), 0) AS Porta_Banner,',
'    NVL(SUM(CASE WHEN b.TIP_RESERVAS = ''Mezanino''     THEN 1 ELSE 0 END), 0) AS Mezanino',
'FROM DIAS d',
'LEFT JOIN BASE b',
'   ON d.ORDEM = CASE TO_CHAR(b.ORDEM)',
'                  WHEN ''1'' THEN 7  -- domingo no fim',
'                  ELSE b.ORDEM - 1',
'                END',
'GROUP BY d.DIA_SEMANA, d.ORDEM',
'ORDER BY d.ORDEM;',
''))
,p_max_row_count=>20
,p_ajax_items_to_submit=>'P12_FILTRO_TIPO,P12_FILTRO_MES,P12_FILTRO_SETOR'
,p_items_value_column_name=>'PORTA_BANNER'
,p_items_label_column_name=>'DIA_SEMANA'
,p_color=>'#fbce4a'
,p_assigned_to_y2=>'off'
,p_items_label_rendered=>true
,p_items_label_position=>'outsideBarEdge'
,p_items_label_display_as=>'PERCENT'
,p_threshold_display=>'onIndicator'
);
end;
