'',
'    IF :P12_FILTRO_MES IS NOT NULL THEN',
'        v_meses := '''''''' || REPLACE(:P12_FILTRO_MES, '':'', '''''','''''') || '''''''';',
'    END IF;',
'',
'    IF :P12_FILTRO_SETOR IS NOT NULL THEN',
'        v_setor := '''''''' || REPLACE(:P12_FILTRO_SETOR, '':'', '''''','''''') || '''''''';',
'    END IF;',
'',
'    v_sql := ''',
'        SELECT',
'            R.TIP_RESERVAS AS LABEL,',
'            ROUND(AVG(TRUNC(R.DAT_FIM) - TRUNC(R.DAT_INICIO) + 1), 2) AS DURACAO_MEDIA,',
'            CASE R.TIP_RESERVAS',
'                WHEN ''''Adesivagem'''' THEN ''''#309fdb''''',
'                WHEN ''''Mezanino'''' THEN ''''#3caf85''''',
'                WHEN ''''Porta-Banner'''' THEN ''''#fbce4a''''',
'                WHEN ''''Porta-Cartaz'''' THEN ''''#e95b54''''',
'            END AS MY_COLOR',
'        FROM',
'            RESERVAS R',
'        JOIN',
'            ATENDIMENTO_RESERVAS AR',
'            ON AR.FK_ATENDIMENTO_RESERVAS_RESERVAS = R.ID_RESERVA',
'        WHERE',
'            R.STATUS IN (''''Confirmado'''', ''''Realizado'''')',
'            AND R.DAT_INICIO IS NOT NULL',
'            AND R.DAT_FIM IS NOT NULL'';',
'',
'    -- Aplica filtros',
'    IF v_tipos IS NOT NULL THEN',
'        v_sql := v_sql || '' AND R.TIP_RESERVAS IN ('' || v_tipos || '')'';',
'    END IF;',
'',
'    IF v_meses IS NOT NULL THEN',
'        v_sql := v_sql || '' AND TO_CHAR(AR.DAT_CRIACAO_ATENDIMENTO, ''''YYYY-MM'''') IN ('' || v_meses || '')'';',
'    END IF;',
'',
'    IF v_setor IS NOT NULL THEN',
'        v_sql := v_sql || ''',
'            AND EXISTS (',
'                SELECT 1 FROM DDA.VINCULO_SF VS',
'                WHERE LPAD(R.COD_PESSOA, 11, ''''0'''') = VS.num_cpf',
'                AND VS.SGL_ORGAO_EXERCICIO IN ('' || v_setor || '')',
'            )'';',
'    END IF;',
'',
'    v_sql := v_sql || ''',
'        GROUP BY',
'            R.TIP_RESERVAS',
'        ORDER BY',
'            R.TIP_RESERVAS'';',
'',
'    RETURN v_sql;',
'END;',
''))
,p_ajax_items_to_submit=>'P12_FILTRO_SETOR,P12_FILTRO_TIPO,P12_FILTRO_MES'
,p_series_name_column_name=>'LABEL'
,p_items_value_column_name=>'DURACAO_MEDIA'
