wwv_flow_imp_page.create_page(
 p_id=>14
,p_name=>'Reserva do Mezanino'
,p_alias=>'RESERVA-DO-MEZANINO'
,p_step_title=>'Reserva do Mezanino'
,p_autocomplete_on_off=>'OFF'
,p_javascript_file_urls=>wwv_flow_string.join(wwv_flow_t_varchar2(
'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/2.16.105/pdf.min.js',
'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/2.16.105/pdf.worker.min.js',
''))
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var datass = '''';',
'var DataArr = [];',
'',
'PDFJS.workerSrc = '''';',
'',
'function setupFileListener() {',
'',
'    apex.server.process(',
'        "NOME_DO_PROCESSO",',
'        {},',
'        {',
'            success: function(pData) {',
'                console.log("pData:", pData);',
'                console.log("COUNT =", pData.count_value);',
'            },',
'            error: function(error) {',
'                console.error("Erro no processo AJAX:", error);',
'            }',
'        }',
'    );',
'',
'    var fileInput = document.querySelector("#P14_ARQ");',
'',
'    if (fileInput) {',
'        fileInput.addEventListener(''change'', function () {',
'            if (this.files && this.files[0]) {',
'                console.log("Arquivo selecionado, iniciando processamento...");',
'                setTimeout(function () {',
'                    ExtractText();',
'                }, 500);',
'            }',
'        });',
'    }',
'}',
'',
'$(document).ready(function () {',
'    setupFileListener();',
'});',
'',
'function ExtractText() {',
'',
'    var fileInput = document.querySelector("#P14_ARQ");',
'    if (!fileInput || !fileInput.files || fileInput.files.length === 0) {',
'        console.error("Nenhum arquivo selecionado!");',
'        return;',
'    }',
'',
'    var file = fileInput.files[0];',
'    var fReader = new FileReader();',
'',
'    fReader.readAsDataURL(file);',
'    fReader.onloadend = function (event) {',
'        convertDataURIToBinary(event.target.result);',
'    };',
'}',
'',
'var BASE64_MARKER = '';base64,'';',
'',
'function convertDataURIToBinary(dataURI) {',
'',
'    var base64Index = dataURI.indexOf(BASE64_MARKER) + BASE64_MARKER.length;',
'    var base64 = dataURI.substring(base64Index);',
'    var raw = window.atob(base64);',
'',
'    var array = new Uint8Array(new ArrayBuffer(raw.length));',
'    for (var i = 0; i < raw.length; i++) {',
'        array[i] = raw.charCodeAt(i);',
'    }',
'',
'    pdfAsArray(array);',
'}',
'',
'function getPageText(pageNum, pdf) {',
'    return new Promise(function (resolve) {',
'        pdf.getPage(pageNum).then(function (page) {',
'            page.getTextContent().then(function (textContent) {',
'                var text = textContent.items.map(i => i.str).join(" ");',
'                resolve(text);',
'            });',
'        });',
'    });',
'}',
'',
'function pdfAsArray(pdfArray) {',
'',
'    PDFJS.getDocument(pdfArray).then(function (pdf) {',
'',
'        var promises = [];',
'        for (var i = 1; i <= pdf.pdfInfo.numPages; i++) {',
'            promises.push(getPageText(i, pdf));',
'        }',
'',
'        Promise.all(promises).then(function (pagesText) {',
'',
'            let textoCompleto = pagesText.join(" ");',
'',
'            let textoBruto = textoCompleto',
'                .replace(/\u00A0/g, " ");',
'',
'            let textoNumerico = textoBruto',
'                .replace(/(\d)\s*:\s*(\d)/g, "$1:$2")',
'                .replace(/(\d{2}\/\d{2})\s*\/\s*(\d{4})/g, "$1/$2");',
'',
'            let normalizedText = textoNumerico',
'                .replace(/\s+/g, " ")',
'                .trim();',
'',
'            console.log("Texto bruto:", textoBruto);',
'            console.log("Texto normalizado:", normalizedText);',
'',
'            // Evento',
'            let eventoMatch = textoBruto.match(/Nome do evento\s+(.+?)\s+Tema/i);',
'            if (eventoMatch) {',
'                let evento = eventoMatch[1]',
'                    .replace(/\s{2,}/g, " ")',
'                    .trim();',
'',
'                apex.item("P14_TITULO_RESERVA").setValue(evento);',
'            }',
'',
unistr('            // Nome respons\00E1vel'),
unistr('            let nomeMatch = textoBruto.match(/Nome\005Cs+([A-Z\00C0-\00FF][A-Z\00C0-\00FF\005Cs]+?)\005Cs+CPF/i);'),
'            if (nomeMatch) {',
'                apex.item("P14_NOME_SOLICITANTE").setValue(',
'                    nomeMatch[1].replace(/\s{2,}/g, " ").trim()',
'                );',
'            }',
'',
'            // Quantidade',
'            let qtdMatch = normalizedText.match(/Quantidade\s+estimada\s+de\s+convidados\s+(\d+)/i);',
'            if (qtdMatch) {',
'                apex.item("P14_NUM_PARTICIPANTES").setValue(qtdMatch[1]);',
'            }',
'',
unistr('            // Descri\00E7\00E3o'),
'            let descMatch = textoBruto.match(',
unistr('                /Descreva\005Cs+detalhadamente\005Cs+como\005Cs+ser\00E1\005Cs+a\005Cs+realiza\00E7\00E3o\005Cs+do\005Cs+evento:\005Cs*(.+?)\005Cs+2\005Cs*\005C.\005Cs*ROTEIRO/i'),
'            );',
'',
'            if (descMatch) {',
'                apex.item("P14_DES_RESERVA").setValue(',
'                    descMatch[1].replace(/\s{2,}/g, " ").trim()',
'                );',
'            }',
'',
'            let datas = [...normalizedText.matchAll(/Data\s+(\d{2}\/\d{2}\/\d{4})/gi)];',
'',
'            let horarios = [...normalizedText.matchAll(',
unistr('                /Hor\00E1rio\005Cs+de\005Cs+in\00EDcio\005Cs+e\005Cs+t\00E9rmino\005Cs+(\005Cd{1,2})\005Cs*:\005Cs*(\005Cd{2})\005Cs+(\005Cd{1,2})\005Cs*:\005Cs*(\005Cd{2})/gi'),
'            )];',
'',
'            let periodos = [];',
'',
'            for (let i = 0; i < datas.length && i < horarios.length; i++) {',
'                periodos.push({',
'                    data: datas[i][1],',
'                    horaIni: horarios[i][1] + ":" + horarios[i][2],',
'                    horaFim: horarios[i][3] + ":" + horarios[i][4]',
'                });',
'            }',
'',
unistr('            console.log("Per\00EDodos encontrados:", periodos);'),
'',
'            periodos.forEach(p => {',
'                apex.server.process(',
'                    "INSERE_TEMP_RESERVAS",',
'                    {',
'                        x01: apex.item("P14_NOME_SOLICITANTE").getValue(),',
'                        x02: p.data,',
'                        x03: p.horaIni,',
'                        x04: p.horaFim',
'                    },',
'                    {',
'                        success: function () {',
'                            console.log("Inserido:", p);',
'                        },',
'                        error: function (err) {',
'                            console.error("Erro ao inserir:", err);',
'                        }',
'                    }',
'                );',
'            });',
'',
'        });',
'',
'    }, function (err) {',
'        console.error("Erro ao carregar PDF:", err);',
'    });',
'}',
''))
