wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1569921948616427338)
,p_plug_name=>'Datas Mezanino'
,p_region_name=>'DATAS_MEZANINO'
,p_parent_plug_id=>wwv_flow_imp.id(1534483800218648479)
,p_region_css_classes=>'calendario-mez'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_escape_on_http_output=>'Y'
,p_plug_template=>wwv_flow_imp.id(341738481904707171)
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ''Temp'' AS origem,',
'       CPF_SOLICITANTE,',
'       NULL AS id_reserva,',
'       HOR_INICIO,',
'       HOR_FIM,',
'       DAT,',
'       TO_TIMESTAMP(TO_CHAR(DAT, ''YYYY-MM-DD'') || '' '' || HOR_INICIO, ''YYYY-MM-DD HH24:MI'') AS start_date,',
'       HOR_INICIO || '' - '' || HOR_FIM AS descricao,',
'       CASE',
'         WHEN LPAD(CPF_SOLICITANTE, 11, ''0'') = :P14_CPF_SOLICITANTE',
'              THEN ''horario_usuario_atual''',
'         ELSE ''horario_analise''',
'       END AS class_name',
'FROM TMP_RESERVAS',
'',
'UNION ALL',
'',
'SELECT ''Mezanino'' AS origem,',
'       r.COD_PESSOA AS FK_ID_PESSOA_RESERVA,',
'       m.id_reserva,',
'       m.hor_inicio,',
'       m.hor_fim,',
'       m.dat,',
'       TO_TIMESTAMP(TO_CHAR(m.dat, ''YYYY-MM-DD'') || '' '' || m.hor_inicio, ''YYYY-MM-DD HH24:MI'') AS start_date,',
'       m.hor_inicio || '' - '' || m.hor_fim AS descricao,',
'       CASE',
'         WHEN LPAD(r.COD_PESSOA, 11, ''0'') = :P14_CPF_SOLICITANTE THEN ''horario_usuario''',
'         WHEN r.status = ''Em Andamento'' THEN ''horario_analise''',
'         ELSE ''horario_confirmado''',
'       END AS class_name',
'FROM horarios_mezanino m',
'JOIN reservas r ON r.id_reserva = m.id_reserva;',
''))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CSS_CALENDAR'
,p_ajax_items_to_submit=>'P14_CPF_SOLICITANTE'
,p_plugin_init_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function ( pOptions) {',
'    pOptions.eventOrder = "start";                               ',
'    return pOptions;',
'}'))
,p_attribute_01=>'START_DATE'
,p_attribute_03=>'DESCRICAO'
,p_attribute_05=>'f?p=&APP_ID.:109:&SESSION.::&DEBUG.:109:P109_ID_RESERVA,P109_HORA_INICIO,P109_HORA_FIM:&ID_RESERVA.,&HOR_INICIO.,&HOR_FIM.'
,p_attribute_06=>'f?p=&APP_ID.:107:&SESSION.::&DEBUG.:107:P107_DAT,P107_CPF_SOLICITANTE:&APEX$NEW_START_DATE.,&P14_CPF_SOLICITANTE.'
