wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1569923325246427352)
,p_plug_name=>'Reservas Pendentes'
,p_parent_plug_id=>wwv_flow_imp.id(1569923198191427350)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(341728690632707168)
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT r.ID_RESERVA,',
'       r.DAT_INICIO,',
'       r.DAT_FIM,',
'       r.TIP_RESERVAS,',
'       CASE ',
'         WHEN r.num_participantes IS NULL THEN ''---'' ',
'         ELSE TO_CHAR(r.num_participantes) ',
'       END AS num_participantes,',
'       r.TITULO_RESERVA,',
'       r.DES_RESERVA,',
'       (',
'         SELECT DISTINCT INITCAP(v.nom_pessoa)',
'           FROM dda.vinculo_sf v',
'          WHERE v.num_cpf = LPAD(r.cod_pessoa, 11, ''0'')',
'          FETCH FIRST 1 ROWS ONLY',
'       ) AS nome_pessoa,',
'       r.PENDENTE,',
'       CASE ',
'         WHEN r.obs IS NULL THEN ''N/A'' ',
'         ELSE r.obs ',
'       END AS observacao,',
'       dbms_lob.getlength(r.ARQ) AS foto,',
'       r.filename,',
'       r.mimetype',
'  FROM RESERVAS r',
' WHERE r.PENDENTE = ''S'' ',
'    AND r.tip_reservas = ''Mezanino''',
' ORDER BY r.dat_inicio, r.tip_RESERVAS, r.id_reserva;',
''))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'MILLIMETERS'
,p_prn_paper_size=>'A4'
,p_prn_width=>297
,p_prn_height=>210
