wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(552566082157236063)
,p_event_id=>wwv_flow_imp.id(552565515266236061)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_name=>'Capturar CPF'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_cpf VARCHAR2(11);',
'BEGIN',
'    IF :P14_NOME_SOLICITANTE IS NULL THEN',
'        RAISE_APPLICATION_ERROR(-20010, ''Por favor, informe o nome do solicitante.'');',
'    END IF;',
'',
'    SELECT num_cpf',
'    INTO :P14_CPF_SOLICITANTE',
'    FROM dda.vinculo_sf',
'    WHERE TRANSLATE(LOWER(nom_pessoa),',
unistr('                    ''\00E3\00E2\00E1\00E0\00E4\00BF\00EA\00E9\00E8\00EB\00EE\00ED\00EC\00EF\00F5\00F4\00F3\00F2\00F6\00FB\00FA\00F9\00FC\00E7'','),
'                    ''aaaaaeeeeeiiiiooooouuuuc'') LIKE',
'          TRANSLATE(LOWER(:P14_NOME_SOLICITANTE),',
unistr('                    ''\00E3\00E2\00E1\00E0\00E4\00BF\00EA\00E9\00E8\00EB\00EE\00ED\00EC\00EF\00F5\00F4\00F3\00F2\00F6\00FB\00FA\00F9\00FC\00E7'','),
'                    ''aaaaaeeeeeiiiiooooouuuuc'') || ''%''',
'      AND ROWNUM = 1;',
'',
'END;'))
,p_attribute_02=>'P14_NOME_SOLICITANTE'
,p_attribute_03=>'P14_CPF_SOLICITANTE'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
