wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(550799154397926687)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'INSERE_TEMP_RESERVAS'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_nome        VARCHAR2(4000) := apex_application.g_x01;',
'    l_data        VARCHAR2(10)   := apex_application.g_x02;',
'    l_hora_ini    VARCHAR2(10)   := apex_application.g_x03;',
'    l_hora_fim    VARCHAR2(10)   := apex_application.g_x04;',
'',
'    l_cpf         VARCHAR2(11);',
'    l_count     NUMBER;',
'BEGIN',
'    -- 1) VALIDAR NOME',
'    IF l_nome IS NULL THEN',
'        RAISE_APPLICATION_ERROR(-20010, ''Por favor, informe o nome do solicitante.'');',
'    END IF;',
'',
unistr('    -- 2) BUSCAR CPF DO NOME (igual seu c\00F3digo anterior)'),
'    SELECT num_cpf',
'      INTO l_cpf',
'      FROM dda.vinculo_sf',
'     WHERE TRANSLATE(LOWER(nom_pessoa),',
unistr('                     ''\00E3\00E2\00E1\00E0\00E4\00BF\00EA\00E9\00E8\00EB\00EE\00ED\00EC\00EF\00F5\00F4\00F3\00F2\00F6\00FB\00FA\00F9\00FC\00E7'','),
'                     ''aaaaaeeeeeiiiiooooouuuuc'')',
'           LIKE',
'           TRANSLATE(LOWER(l_nome),',
unistr('                     ''\00E3\00E2\00E1\00E0\00E4\00BF\00EA\00E9\00E8\00EB\00EE\00ED\00EC\00EF\00F5\00F4\00F3\00F2\00F6\00FB\00FA\00F9\00FC\00E7'','),
'                     ''aaaaaeeeeeiiiiooooouuuuc'') || ''%''',
'       AND ROWNUM = 1;',
'',
'    SELECT COUNT(*) INTO l_count',
'    FROM tmp_reservas',
'    WHERE cpf_solicitante = l_cpf',
'        AND dat = TO_DATE(l_data, ''DD/MM/YYYY'')',
'        AND hor_inicio = l_hora_ini',
'        AND hor_fim = l_hora_fim;',
'',
'    IF l_count > 0 THEN',
'        apex_json.open_object;',
'        apex_json.write(''status'', ''duplicado'');',
unistr('        apex_json.write(''msg'', ''J\00E1 existe uma reserva id\00EAntica para este CPF.'');'),
'        apex_json.close_object;',
'        RETURN;',
'    END IF;',
'',
'    -- 3) INSERIR NA TMP_RESERVAS',
'    INSERT INTO tmp_reservas (',
'        cpf_solicitante,',
'        dat,',
'        hor_inicio,',
'        hor_fim,',
'        dat_criacao',
'    ) VALUES (',
'        l_cpf,',
'        TO_DATE(l_data, ''DD/MM/YYYY''),',
'        l_hora_ini,',
'        l_hora_fim,',
'        SYSDATE',
'    );',
'',
'    -- 4) RETORNAR DADOS PRO JAVASCRIPT (se quiser)',
'    apex_json.open_object;',
'    apex_json.write(''cpf'', l_cpf);',
'    apex_json.write(''status'', ''ok'');',
'    apex_json.close_object;',
'',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>350026162159827742
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(553406629025770546)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'NOME_DO_PROCESSO'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_count NUMBER;',
'BEGIN',
'    SELECT COUNT(*)',
'    INTO v_count',
'    FROM apex_application_temp_files',
'    WHERE name = :P14_ARQ;',
'',
'    apex_json.open_object;',
'    apex_json.write(''count_value'', v_count);',
'    apex_json.close_object;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>352633636787671601
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(552554846233236038)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Inserir no BD'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_blob          BLOB;',
'    l_mime          VARCHAR2(200);',
'    l_filename      VARCHAR2(200);',
'    l_data_ini      DATE;',
'    l_data_fim      DATE;',
'    l_id_reserva    reservas.id_reserva%TYPE;',
'    l_nome_asqualog VARCHAR2(300);',
'',
'    v_data_atual    DATE := TRUNC(SYSDATE);',
'    v_data_reserva  DATE;',
'    v_hora_inicio   DATE;',
'    v_hora_fim      DATE;',
'    v_data_limite   DATE;',
'    v_dias_uteis    NUMBER := 0;',
'    v_count         NUMBER;',
'BEGIN',
'    SELECT MIN(dat), MAX(dat)',
'    INTO l_data_ini, l_data_fim',
'    FROM TMP_RESERVAS',
'    WHERE LPAD(cpf_solicitante, 11, ''0'') = :P14_CPF_SOLICITANTE;',
'',
'    IF l_data_ini IS NULL OR l_data_fim IS NULL THEN',
unistr('        RAISE_APPLICATION_ERROR(-20011, ''As datas de in\00EDcio e fim devem ser informadas.'');'),
'    END IF;',
'',
'    FOR r IN (',
'        SELECT dat,',
'               TO_DATE(hor_inicio, ''HH24:MI'') AS hor_inicio,',
'               TO_DATE(hor_fim,   ''HH24:MI'') AS hor_fim',
'          FROM tmp_reservas',
'         WHERE LPAD(cpf_solicitante, 11, ''0'') = :P14_CPF_SOLICITANTE',
'    )',
'    LOOP',
'        v_data_reserva := r.dat;',
'        v_hora_inicio  := r.hor_inicio;',
'        v_hora_fim     := r.hor_fim;',
'',
'        IF v_data_reserva < v_data_atual THEN',
'            RAISE_APPLICATION_ERROR(',
'                -20012,',
unistr('                ''N\00E3o \00E9 poss\00EDvel fazer reservas para datas passadas: '''),
'                || TO_CHAR(v_data_reserva, ''DD/MM/YYYY'')',
'                || CHR(10)',
unistr('                || ''Compare os dados dos campos com o formul\00E1rio da Primeira Secretaria.'''),
'            );',
'        END IF;',
'',
'        v_data_limite := v_data_atual;',
'        v_dias_uteis  := 0;',
'',
'        WHILE v_dias_uteis < 2 LOOP',
'            v_data_limite := v_data_limite + 1;',
'',
'            IF TO_CHAR(v_data_limite, ''D'') BETWEEN ''2'' AND ''6'' THEN',
'                v_dias_uteis := v_dias_uteis + 1;',
'            END IF;',
'        END LOOP;',
'',
'        IF v_data_reserva < v_data_limite THEN',
'            RAISE_APPLICATION_ERROR(',
'                -20013,',
unistr('                ''\00C9 necess\00E1rio no m\00EDnimo 2 dias \00FAteis de anteced\00EAncia. Data m\00EDnima: '''),
'                || TO_CHAR(v_data_limite, ''DD/MM/YYYY'')',
'                || CHR(10)',
unistr('                || ''Compare os dados dos campos com o formul\00E1rio da Primeira Secretaria.'''),
'            );',
'        END IF;',
'',
'        IF v_hora_inicio >= v_hora_fim THEN',
'            RAISE_APPLICATION_ERROR(',
'                -20014,',
unistr('                ''A hora de in\00EDcio deve ser menor que a hora fim.'''),
'                || CHR(10)',
unistr('                || ''Compare os dados dos campos com o formul\00E1rio da Primeira Secretaria.'''),
'            );',
'        END IF;',
'',
'        IF (v_hora_inicio < TO_DATE(''14:00'', ''HH24:MI'')',
'            AND v_hora_fim > TO_DATE(''12:00'', ''HH24:MI''))',
'        THEN',
'            RAISE_APPLICATION_ERROR(',
'                -20015,',
unistr('                ''N\00E3o \00E9 permitido reservar entre 12:00 e 14:00 (hor\00E1rio de almo\00E7o).'''),
'                || CHR(10)',
unistr('                || ''Compare os dados dos campos com o formul\00E1rio da Primeira Secretaria.'''),
'            );',
'        END IF;',
'',
'        SELECT COUNT(*)',
'          INTO v_count',
'          FROM horarios_mezanino',
'         WHERE dat = v_data_reserva',
'           AND (',
'                    v_hora_inicio <  TO_DATE(hor_fim,''HH24:MI'')',
'                AND v_hora_fim    >  TO_DATE(hor_inicio,''HH24:MI'')',
'                OR v_hora_inicio  BETWEEN (TO_DATE(hor_inicio,''HH24:MI'') - 1/24)',
'                                    AND    (TO_DATE(hor_fim,''HH24:MI'')    + 1/24)',
'                OR v_hora_fim     BETWEEN (TO_DATE(hor_inicio,''HH24:MI'') - 1/24)',
'                                    AND    (TO_DATE(hor_fim,''HH24:MI'')    + 1/24)',
'                OR TO_DATE(hor_inicio,''HH24:MI'')',
'                       BETWEEN (v_hora_inicio - 1/24)',
'                           AND (v_hora_fim    + 1/24)',
'               );',
'',
'        IF v_count > 0 THEN',
'            RAISE_APPLICATION_ERROR(',
'                -20016,',
unistr('                ''Conflito com reserva existente. M\00EDnimo de 1h de intervalo necess\00E1rio.'''),
'                || CHR(10)',
unistr('                || ''Compare os dados dos campos com o formul\00E1rio da Primeira Secretaria.'''),
'            );',
'        END IF;',
'',
'        SELECT COUNT(*)',
'          INTO v_count',
'          FROM tmp_reservas t',
'         WHERE t.dat = v_data_reserva',
'           AND LPAD(t.cpf_solicitante, 11, ''0'') = LPAD(:P14_CPF_SOLICITANTE, 11, ''0'')',
'           AND NOT (',
'                t.hor_inicio = TO_CHAR(v_hora_inicio,''HH24:MI'')',
'                AND t.hor_fim = TO_CHAR(v_hora_fim,''HH24:MI'')',
'           )',
'           AND (',
'                    v_hora_inicio <  TO_DATE(t.hor_fim,''HH24:MI'')',
'                AND v_hora_fim    >  TO_DATE(t.hor_inicio,''HH24:MI'')',
'                OR v_hora_inicio  BETWEEN (TO_DATE(t.hor_inicio,''HH24:MI'') - 1/24)',
'                                    AND    (TO_DATE(t.hor_fim,''HH24:MI'')    + 1/24)',
'                OR v_hora_fim     BETWEEN (TO_DATE(t.hor_inicio,''HH24:MI'') - 1/24)',
'                                    AND    (TO_DATE(t.hor_fim,''HH24:MI'')    + 1/24)',
'                OR TO_DATE(t.hor_inicio,''HH24:MI'')',
'                       BETWEEN (v_hora_inicio - 1/24)',
'                           AND (v_hora_fim    + 1/24)',
'               );',
'',
'        IF v_count > 0 THEN',
'            RAISE_APPLICATION_ERROR(',
'                -20017,',
unistr('                ''Conflito entre hor\00E1rios inseridos. M\00EDnimo de 1h de intervalo necess\00E1rio.'''),
'                || CHR(10)',
unistr('                || ''Compare os dados dos campos com o formul\00E1rio da Primeira Secretaria.'''),
'            );',
'        END IF;',
'    END LOOP;',
'',
'    IF :P14_ARQ IS NOT NULL THEN',
'        SELECT blob_content, mime_type, filename',
'        INTO l_blob, l_mime, l_filename',
'        FROM apex_application_temp_files',
'        WHERE name = :P14_ARQ;',
'    END IF;',
'',
'    INSERT INTO reservas (',
'        id_reserva,',
'        dat_inicio,',
'        dat_fim,',
'        tip_reservas,',
'        status,',
'        loc,',
'        num_participantes,',
'        titulo_reserva,',
'        des_reserva,',
'        cod_pessoa,',
'        pendente,',
'        obs,',
'        arq,',
'        mimetype,',
'        filename,',
'        email_enviado,',
'        dat_criacao',
'    )',
'    VALUES (',
'        SEQ_RESERVAS.NEXTVAL,',
'        l_data_ini,',
'        l_data_fim,',
'        :P14_TIP_RESERVAS,',
'        ''Confirmado'',',
'        NULL,',
'        :P14_NUM_PARTICIPANTES,',
'        :P14_TITULO_RESERVA,',
'        :P14_DES_RESERVA,',
'        :P14_CPF_SOLICITANTE,',
'        ''S'',',
'        :P14_OBS,',
'        l_blob,',
'        l_mime,',
'        l_filename,',
'        ''N'',',
'        SYSDATE',
'    )',
'    RETURNING id_reserva INTO l_id_reserva;',
'',
'    INSERT INTO horarios_mezanino (',
'        id_horario,',
'        id_reserva,',
'        dat,',
'        hor_inicio,',
'        hor_fim',
'    )',
'    SELECT SEQ_HORARIOS_MEZANINO.NEXTVAL,',
'           l_id_reserva,',
'           dat,',
'           hor_inicio,',
'           hor_fim',
'      FROM tmp_reservas',
'     WHERE LPAD(cpf_solicitante, 11, ''0'') = :P14_CPF_SOLICITANTE;',
'',
'    DELETE FROM tmp_reservas',
'     WHERE LPAD(cpf_solicitante, 11, ''0'') = :P14_CPF_SOLICITANTE;',
'',
'    :P14_ID_RESERVA       := l_id_reserva;',
'    :P14_NOME_SOLICITANTE := '''';',
'    :P14_CPF_SOLICITANTE  := '''';',
'',
'    SELECT nom_pessoa INTO l_nome_asqualog',
'        FROM dda.vinculo_sf',
'        WHERE num_cpf = ',
'            CASE',
'                WHEN REGEXP_LIKE(:APP_USER, ''^\d+$'')',
'                    THEN :APP_USER',
'                ELSE (',
'                    SELECT u.num_cpf_pessoa',
'                    FROM dda.usuario_rede u',
'                    WHERE LOWER(u.txt_email_sf) = LOWER(:APP_USER) || ''@senado.leg.br''',
'                )',
'            END',
'          AND ind_vinculo_ativo = ''S'';',
'',
'    INSERT INTO atendimento_reservas (',
'        dat_criacao_atendimento,',
'        des_atendimento,',
'        nom_atendimento,',
'        fk_atendimento_reservas_reservas,',
'        confirmado',
'    ) VALUES (',
'        SYSDATE,',
unistr('        ''Registro da Solicita\00E7\00E3o'','),
'        l_nome_asqualog,',
'        l_id_reserva,',
'        ''S''',
'    );',
'    ',
'    INSERT INTO atendimento_reservas (',
'        dat_criacao_atendimento,',
'        des_atendimento,',
'        nom_atendimento,',
'        fk_atendimento_reservas_reservas,',
'        confirmado',
'    ) VALUES (',
'        SYSDATE,',
unistr('        ''Confirma\00E7\00E3o da reserva.'','),
'        l_nome_asqualog,',
'        l_id_reserva,',
'        ''S''',
'    );',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>351781853995137093
);
end;
