wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(563343016126870876)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Alterar o Campo Pendente'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    CURSOR c_solicitante IS',
'        SELECT DISTINCT LPAD(cod_pessoa, 11, ''0'') AS cpf_solicitante',
'        FROM reservas',
'        WHERE tip_reservas = ''Mezanino''',
'            AND pendente = ''S'';',
'',
'    v_email_destino     VARCHAR2(200);',
'    v_email_remetente   VARCHAR2(200) := ''asqualog@senado.leg.br'';',
'    v_assunto           VARCHAR2(300);',
'    v_msg               CLOB;',
'    v_nome_solicitante  VARCHAR2(300);',
'    v_nome_asqualog     VARCHAR2(300);',
'BEGIN',
'    SELECT INITCAP(nom_pessoa) INTO v_nome_asqualog',
'    FROM dda.vinculo_sf',
'    WHERE num_cpf = ',
'        CASE',
'            WHEN REGEXP_LIKE(:APP_USER, ''^\d+$'')',
'                THEN :APP_USER',
'            ELSE (',
'                SELECT u.num_cpf_pessoa',
'                FROM dda.usuario_rede u',
'                WHERE LOWER(u.txt_email_sf) = LOWER(:APP_USER) || ''@senado.leg.br''',
'            )',
'        END',
'        AND ind_vinculo_ativo = ''S'';',
'',
'    FOR sol IN c_solicitante LOOP',
'        BEGIN',
'            SELECT u.txt_email_sf, v.nom_pessoa',
'            INTO v_email_destino, v_nome_solicitante',
'            FROM dda.usuario_rede u',
'            JOIN dda.vinculo_sf v ON u.num_cpf_pessoa = v.num_cpf',
'            WHERE u.num_cpf_pessoa = sol.cpf_solicitante;',
'        EXCEPTION',
'            WHEN NO_DATA_FOUND THEN',
'                CONTINUE;',
'        END;',
'',
'        v_msg := ''<p>Prezado(a) <strong>'' || v_nome_solicitante || ''</strong>,</p>'' ||',
'             ''<p>Informamos que as seguintes reservas de Mezanino foram ''',
'             || ''<strong><span style="color: green;">confirmadas</span></strong>:</p>'';',
'',
'        FOR r IN (',
'            SELECT id_reserva,',
'                titulo_reserva,',
'                des_reserva,',
'                num_participantes',
'            FROM reservas',
'            WHERE tip_reservas = ''Mezanino''',
'                AND pendente = ''S''',
'                AND LPAD(cod_pessoa, 11, ''0'') = sol.cpf_solicitante',
'        )',
'        LOOP',
'',
'            v_msg := v_msg ||',
'                         ''<hr>'' ||',
'                         ''<strong>Evento:</strong> '' || r.titulo_reserva || ''<br>'' ||',
unistr('                         ''<strong>Descri\00E7\00E3o:</strong> '' || r.des_reserva || ''<br>'' ||'),
unistr('                         ''<strong>N\00BA de Participantes:</strong> '' || r.num_participantes || ''<br>'' ||'),
unistr('                         ''<strong>Hor\00E1rios reservados:</strong><br>'';'),
'',
'            FOR h IN (',
'                SELECT TO_CHAR(dat, ''DD/MM/YYYY'') AS data_str,',
'                    hor_inicio,',
'                    hor_fim',
'                FROM horarios_mezanino',
'                WHERE id_reserva = r.id_reserva',
'                ORDER BY dat, hor_inicio',
'            )',
'            LOOP',
'                v_msg := v_msg ||',
unistr('                        ''&nbsp;&nbsp;- '' || h.data_str || '': '' || h.hor_inicio || '' \00E0s '' || h.hor_fim || ''<br>'';'),
'            END LOOP;',
'        END LOOP;',
'',
'        v_msg := v_msg ||',
unistr('                 ''<p><br>Suas reservas agora est\00E3o confirmadas e ser\00E3o executadas conforme solicitado.</p>'' ||'),
'                 ''<p>Atenciosamente,</p>'';',
'',
'        v_msg := v_msg ||',
'            ''<br><br>'' ||',
'            ''<p style="color:#003A6B; font-family: Arial, sans-serif; font-size: 13px;">'' ||',
'            v_nome_asqualog ||',
unistr('            ''<br>Assessoria de Qualidade de Atendimento e Log\00EDstica \2013 ASQUALOG/DGER<br>'' ||'),
'            ''Diretoria-Geral<br>'' ||',
'            ''Bloco 10/Sala 17<br><br>'' ||',
'            ''<img src="/mnt/data/c08c4ea1-3045-4606-9ac5-554a631d1888.png" '' ||',
'            ''alt="Senado Federal" style="width:160px;">'' ||',
'            ''</p>'';',
'',
'        APEX_MAIL.SEND(',
'            p_to        => v_email_destino,',
'            p_from      => v_email_remetente,',
unistr('            p_subj      => ''Confirma\00E7\00E3o de Reservas de Mezanino - '' || v_nome_solicitante,'),
'            p_body      => NULL,',
'            p_body_html => v_msg',
'        );',
'',
'        UPDATE reservas SET pendente = ''N''',
'        WHERE tip_reservas = ''Mezanino''',
'           AND pendente = ''S''',
'           AND LPAD(cod_pessoa, 11, ''0'') = sol.cpf_solicitante;    ',
'',
'    END LOOP;',
'',
'    COMMIT;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>362570023888771931
);
end;
