'var tipo = $v("P106_TIP_RESERVAS").toLowerCase();',
'',
'if (tipo.startsWith("porta")) {',
'    apex.item("P106_LOC").show();',
'    apex.item("P106_DAT_INICIO").show();',
'    apex.item("P106_DAT_FIM").show();',
'',
'    $s("P106_NUM_PARTICIPANTES", "");',
'    $("#datas_mezanino").hide();',
'    apex.item("P106_NUM_PARTICIPANTES").hide();',
'} else if (tipo === "mezanino") {',
'    apex.item("P106_NUM_PARTICIPANTES").show();',
'    $("#datas_mezanino").show();',
'',
'    $s("P106_LOC", "");',
'    apex.item("P106_DAT_INICIO").hide();',
'    apex.item("P106_DAT_FIM").hide();',
'    apex.item("P106_LOC").hide();',
'} else if (tipo === "adesivagem") {',
'    apex.item("P106_DAT_INICIO").show();',
'    apex.item("P106_DAT_FIM").show();',
'',
'    apex.item("P106_LOC").hide();',
'    $("#datas_mezanino").hide();',
'    apex.item("P106_NUM_PARTICIPANTES").hide();',
'} else {',
'    apex.item("P106_LOC").show();',
'    apex.item("P106_NUM_PARTICIPANTES").show();',
'}'))
);
