wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(363326569455894173)
,p_event_id=>wwv_flow_imp.id(363326396118894172)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_count NUMBER;',
'    v_data_reserva DATE;',
'    v_data_limite DATE;',
'    v_dias_uteis NUMBER := 0;',
'    v_data_atual DATE := TRUNC(SYSDATE);',
'    v_hora_inicio DATE;',
'    v_hora_fim  DATE;',
'    v_msg   VARCHAR2(4000);',
'BEGIN',
'    :P107_ERROR_MESSAGE := '''';',
'    ',
'    IF :P107_DAT IS NULL OR :P107_HOR_INICIO IS NULL OR :P107_HOR_FIM IS NULL THEN',
unistr('        :P107_ERROR_MESSAGE := ''Todos os campos s\00E3o obrigat\00F3rios.'';'),
'        RETURN;',
'    END IF;',
'    ',
'    v_data_reserva := TO_DATE(:P107_DAT, ''DD/MM/YYYY'');',
'    v_hora_inicio := TO_DATE(:P107_HOR_INICIO, ''HH24:MI'');',
'    v_hora_fim := TO_DATE(:P107_HOR_FIM, ''HH24:MI'');',
'',
'    IF v_data_reserva < v_data_atual THEN',
unistr('        :P107_ERROR_MESSAGE := ''N\00E3o \00E9 poss\00EDvel fazer reservas para datas passadas.'';'),
'        RETURN;',
'    END IF;',
'        ',
'    v_data_limite := v_data_atual;',
'    WHILE v_dias_uteis < 2 LOOP',
'        v_data_limite := v_data_limite + 1;',
'        IF TO_CHAR(v_data_limite, ''D'') BETWEEN ''2'' AND ''6'' THEN',
'            v_dias_uteis := v_dias_uteis + 1;',
'        END IF;',
'    END LOOP;',
'    ',
'    IF v_data_reserva < v_data_limite THEN',
unistr('        :P107_ERROR_MESSAGE := ''N\00E3o \00E9 poss\00EDvel fazer reservas com menos de 2 dias \00FAteis de anteced\00EAncia. Data m\00EDnima permitida: '' || TO_CHAR(v_data_limite, ''DD/MM/YYYY'');'),
'        RETURN;',
'    END IF;',
'    ',
'    IF TO_DATE(:P107_HOR_INICIO, ''HH24:MI'') >= TO_DATE(:P107_HOR_FIM, ''HH24:MI'') THEN',
unistr('        :P107_ERROR_MESSAGE := ''A hora de in\00EDcio deve ser menor que a hora de fim.'';'),
'        RETURN;',
'    END IF;',
'',
'    IF (v_hora_inicio < TO_DATE(''14:00'', ''HH24:MI'') AND v_hora_fim > TO_DATE(''12:00'', ''HH24:MI'')) THEN',
unistr('        :P107_ERROR_MESSAGE := ''N\00E3o \00E9 permitido reservar entre 12:00 e 14:00 (hor\00E1rio de almo\00E7o).'';'),
'        RETURN;',
'    END IF;',
'    ',
'    SELECT COUNT(*) INTO v_count',
'    FROM horarios_mezanino',
'    WHERE dat = v_data_reserva',
'        AND (',
'            v_hora_inicio < TO_DATE(hor_fim, ''HH24:MI'')',
'            AND v_hora_fim > TO_DATE(hor_inicio, ''HH24:MI'')',
'            OR v_hora_inicio BETWEEN (TO_DATE(hor_inicio, ''HH24:MI'') - (1/24)) AND (TO_DATE(hor_fim, ''HH24:MI'') + (1/24))',
'            OR v_hora_fim BETWEEN (TO_DATE(hor_inicio, ''HH24:MI'') - (1/24)) AND (TO_DATE(hor_fim, ''HH24:MI'') + (1/24))',
'            OR (TO_DATE(hor_inicio, ''HH24:MI'') BETWEEN (v_hora_inicio - (1/24)) AND (v_hora_fim + (1/24)))',
'        );',
'',
'    IF v_count > 0 THEN  ',
unistr('        :P107_ERROR_MESSAGE := ''Conflito com reserva existente. M\00EDnimo de 1h de intervalo necess\00E1rio.'';'),
'        RETURN;',
'    END IF;',
'',
'    SELECT COUNT(*) INTO v_count  ',
'    FROM tmp_reservas  ',
'    WHERE dat = v_data_reserva',
'      AND (',
'            v_hora_inicio < TO_DATE(hor_fim, ''HH24:MI'')',
'            AND v_hora_fim > TO_DATE(hor_inicio, ''HH24:MI'')',
'            OR v_hora_inicio BETWEEN (TO_DATE(hor_inicio, ''HH24:MI'') - (1/24)) AND (TO_DATE(hor_fim, ''HH24:MI'') + (1/24))',
'            OR v_hora_fim BETWEEN (TO_DATE(hor_inicio, ''HH24:MI'') - (1/24)) AND (TO_DATE(hor_fim, ''HH24:MI'') + (1/24))',
'            OR (TO_DATE(hor_inicio, ''HH24:MI'') BETWEEN (v_hora_inicio - (1/24)) AND (v_hora_fim + (1/24)))',
'          );',
'',
'    IF v_count > 0 THEN',
unistr('        :P107_ERROR_MESSAGE := ''Conflito com reserva existente. M\00EDnimo de 1h de intervalo necess\00E1rio.'';'),
'        RETURN;',
'    END IF;',
'    ',
'    INSERT INTO tmp_reservas (cpf_solicitante, hor_inicio, hor_fim, dat, dat_criacao)',
'    VALUES (:P107_CPF_SOLICITANTE, :P107_HOR_INICIO, :P107_HOR_FIM, v_data_reserva, SYSDATE);',
'    ',
'    :P107_ERROR_MESSAGE := ''SUCCESS'';',
'    ',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        :P107_ERROR_MESSAGE := ''Erro inesperado: '' || SQLERRM;',
'END;'))
,p_attribute_02=>'P107_ID_TEMP,P107_HOR_INICIO,P107_HOR_FIM,P107_CPF_SOLICITANTE,P107_DAT'
,p_attribute_03=>'P107_ERROR_MESSAGE'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
