wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(343453929134155148)
,p_plug_name=>'Detalhes da Reserva'
,p_region_template_options=>'#DEFAULT#:t-Region--removeHeader js-removeLandmark:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(341738481904707171)
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select r.ID_RESERVA,',
'       r.DAT_INICIO,',
'       r.DAT_FIM,',
'       r.TIP_RESERVAS,',
'       r.STATUS,',
'       r.NUM_PARTICIPANTES,',
'       r.TITULO_RESERVA,',
'       r.DES_RESERVA,',
'       v.nom_pessoa,',
'       r.PENDENTE,',
'       r.LOC,',
'       r.JUSTIFICATIVA,',
'       case when r.OBS is null then ''N/A'' else r.OBS end as OBSERVACAO,',
'       r.ARQ,',
'       r.MIMETYPE,',
'       r.FILENAME,',
'       r.COD_GRUPO_RESERVA',
'  from RESERVAS r',
'  join dda.vinculo_sf v on LPAD(r.cod_pessoa, 11, ''0'') = v.num_cpf',
'  where v.ind_vinculo_ativo = ''S'''))
,p_is_editable=>false
,p_plug_source_type=>'NATIVE_FORM'
);
