wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(343455818979155167)
,p_name=>'P201_JUSTIFICATIVA'
,p_source_data_type=>'VARCHAR2'
,p_is_required=>true
,p_item_sequence=>180
,p_item_plug_id=>wwv_flow_imp.id(343453929134155148)
,p_item_source_plug_id=>wwv_flow_imp.id(343453929134155148)
,p_item_default=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    CASE ',
'        WHEN r1.tip_reservas = ''Adesivagem'' THEN ',
'''Reserva confirmada.<br>',
'',
unistr('O demandante dever\00E1 contatar a SEGRAF para solicitar a produ\00E7\00E3o dos adesivos para as mesas do Espa\00E7o do Colaborador.'),
'',
unistr('<br>Esclarecemos que o Espa\00E7o dos Colaboradores conta com 77 mesas no T\00E9rreo e 88 mesas no Mezanino, sendo que cada mesa possui as dimens\00F5es de 0,60m \00D7 0,80m.'),
'',
unistr('<br>Sugerimos que o adesivo n\00E3o cubra toda a superf\00EDcie da mesa e que a adesivagem seja feita de forma intercalada (em uma mesa sim, outra n\00E3o) para manter a harmonia visual do ambiente.'''),
'',
'        WHEN EXISTS (',
'            SELECT 1',
'            FROM reservas r2',
'            WHERE r2.titulo_reserva = r1.titulo_reserva',
'              AND r2.des_reserva    = r1.des_reserva',
'              AND r2.tip_reservas   = r1.tip_reservas',
'              AND r2.dat_inicio     = r1.dat_inicio',
'              AND r2.dat_fim        = r1.dat_fim',
'              AND r2.cod_pessoa     = r1.cod_pessoa',
'              AND r2.id_reserva    <> r1.id_reserva',
'        )',
'        THEN r1.justificativa',
'        ',
'        ELSE r1.justificativa',
'    END AS justificativa',
'FROM reservas r1',
'WHERE r1.id_reserva = :P201_ID_RESERVA;',
''))
,p_item_default_type=>'SQL_QUERY'
,p_prompt=>unistr('D\00EA uma resposta para o solicitante sobre sua decis\00E3o')
,p_source=>'JUSTIFICATIVA'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_TEXTAREA'
,p_cSize=>30
,p_cMaxlength=>4000
,p_cHeight=>5
