wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(343456940482155178)
,p_event_id=>wwv_flow_imp.id(343456705269155176)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('-- Quando algu\00E9m abre os detalhes da reserva, automaticamente o atendimento \00E9 atualizado para ''Reserva est\00E1 sendo analisada'''),
'DECLARE',
'    v_nome VARCHAR2(200);',
'    v_ultimo VARCHAR2(4000);',
'BEGIN',
'    SELECT nom_pessoa INTO v_nome',
'    FROM dda.vinculo_sf',
'    WHERE num_cpf = ',
'        CASE',
'                WHEN REGEXP_LIKE(:APP_USER, ''^\d+$'')',
'                    THEN :APP_USER',
'                ELSE (',
'                    SELECT u.num_cpf_pessoa',
'                    FROM dda.usuario_rede u',
'                    WHERE LOWER(u.txt_email_sf) = LOWER(:APP_USER) || ''@senado.leg.br''',
'                )',
'            END',
'    AND ind_vinculo_ativo = ''S'';',
'',
'    SELECT des_atendimento INTO v_ultimo',
'    FROM (',
'        SELECT des_atendimento',
'        FROM atendimento_reservas',
'        WHERE fk_atendimento_reservas_reservas = :P201_ID_RESERVA',
'        ORDER BY dat_criacao_atendimento DESC',
'    )',
'    WHERE ROWNUM = 1;',
'',
unistr('    IF v_ultimo = ''Registro da Solicita\00E7\00E3o'' THEN'),
'        INSERT INTO atendimento_reservas (',
'            dat_criacao_atendimento,',
'            des_atendimento,',
'            nom_atendimento,',
'            fk_atendimento_reservas_reservas,',
'            confirmado',
'        ) VALUES (',
'            SYSDATE,',
unistr('            ''Reserva est\00E1 sendo analisada.'','),
'            v_nome,',
'            :P201_ID_RESERVA,',
'            ''S''',
'        );',
'    END IF;',
'END;'))
,p_attribute_02=>'P201_ID_RESERVA'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(580650394131579584)
,p_event_id=>wwv_flow_imp.id(343456705269155176)
,p_event_result=>'TRUE'
,p_action_sequence=>30
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_justificativa reservas.justificativa%TYPE;',
'    v_tipo          reservas.tip_reservas%TYPE;',
'BEGIN',
'    -- Primeiro descubro o tipo da reserva atual',
'    SELECT tip_reservas',
'    INTO v_tipo',
'    FROM reservas',
'    WHERE id_reserva = :P201_ID_RESERVA;',
'',
'    -- PRIORIDADE TOTAL',
'    IF v_tipo = ''Adesivagem'' THEN',
'    ',
'        :P201_JUSTIFICATIVA :=',
'''Reserva confirmada.',
' ',
unistr('O demandante dever\00E1 contatar a SEGRAF para solicitar a produ\00E7\00E3o dos adesivos para as mesas do Espa\00E7o do Servidor.'),
' ',
unistr('Esclarecemos que as mesas do local possuem as dimens\00F5es de 0,60m \00D7 0,80m.'),
' ',
unistr('Sugerimos que o adesivo n\00E3o cubra toda a superf\00EDcie da mesa e que a adesivagem seja feita de forma intercalada (em uma mesa sim, outra n\00E3o) para manter a harmonia visual do ambiente.'),
' ',
unistr('Por fim, informamos que caber\00E1 ao demandante providenciar, junto ao setor competente, a retirada dos adesivos ao t\00E9rmino do per\00EDodo do evento.'';'),
'',
'    ELSE',
unistr('        -- N\00E3o \00E9 adesivagem \00BF aplica sua busca'),
'        SELECT r2.justificativa',
'        INTO v_justificativa',
'        FROM reservas r2',
'        WHERE r2.id_reserva <> :P201_ID_RESERVA',
'          AND r2.justificativa IS NOT NULL',
'          AND (r2.titulo_reserva,',
'               r2.des_reserva,',
'               r2.tip_reservas,',
'               r2.dat_inicio,',
'               r2.dat_fim,',
'               r2.cod_pessoa) =',
'              (',
'                SELECT r1.titulo_reserva,',
'                       r1.des_reserva,',
'                       r1.tip_reservas,',
'                       r1.dat_inicio,',
'                       r1.dat_fim,',
'                       r1.cod_pessoa',
'                FROM reservas r1',
'                WHERE r1.id_reserva = :P201_ID_RESERVA',
'              )',
'        FETCH FIRST 1 ROW ONLY;',
'',
'        :P201_JUSTIFICATIVA := v_justificativa;',
'',
'    END IF;',
'',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        :P201_JUSTIFICATIVA := NULL;',
'END;',
''))
,p_attribute_02=>'P201_ID_RESERVA'
,p_attribute_03=>'P201_JUSTIFICATIVA'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
