wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(343454058636155149)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_region_id=>wwv_flow_imp.id(343453929134155148)
,p_process_type=>'NATIVE_FORM_INIT'
,p_process_name=>'Inicializar o form Confirmar ou Cancelar Reserva'
,p_internal_uid=>142681066398056204
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(382983241742560451)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_region_id=>wwv_flow_imp.id(343453929134155148)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'CONFIRMAR_OU_CANCELAR_RESERVA'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Confirma ou cancela a reserva e coloca a justificativa dada',
'DECLARE',
'    v_nome          VARCHAR2(200);',
'    v_status_atual  VARCHAR2(50);',
'    v_id_reserva    NUMBER := TO_NUMBER(APEX_APPLICATION.G_X01);',
'    v_justificativa VARCHAR2(4000);',
'    v_acao          VARCHAR2(50) := APEX_APPLICATION.G_X03;',
'BEGIN',
'    v_justificativa := APEX_APPLICATION.G_X02;',
'',
'    IF v_justificativa IS NULL OR TRIM(v_justificativa) IS NULL THEN',
unistr('        htp.p(''{"status":"erro","mensagem":"Escreva uma justificativa/resposta sobre sua decis\00E3o."}'');'),
'        RETURN;',
'    END IF;',
'',
'    SELECT nom_pessoa INTO v_nome',
'    FROM dda.vinculo_sf',
'    WHERE num_cpf = ',
'        CASE',
'                WHEN REGEXP_LIKE(:APP_USER, ''^\d+$'')',
'                    THEN :APP_USER',
'                ELSE (',
'                    SELECT u.num_cpf_pessoa',
'                    FROM dda.usuario_rede u',
'                    WHERE LOWER(u.txt_email_sf) = LOWER(:APP_USER) || ''@senado.leg.br''',
'                )',
'            END',
'      AND ind_vinculo_ativo = ''S'';',
'',
'    SELECT status INTO v_status_atual',
'    FROM reservas',
'    WHERE id_reserva = v_id_reserva;',
'',
'    IF v_acao = ''Confirmar'' THEN',
'        IF v_status_atual = ''Confirmado'' THEN',
unistr('            htp.p(''{"status":"erro","mensagem":"A reserva j\00E1 est\00E1 confirmada."}'');'),
'            RETURN;',
'        ELSE',
'            UPDATE reservas',
'            SET justificativa = v_justificativa,',
'                status = ''Confirmado''',
'            WHERE id_reserva = v_id_reserva;',
'',
'            -- Atualiza o atendimento confirmando a reserva',
'            INSERT INTO atendimento_reservas (',
'                dat_criacao_atendimento,',
'                des_atendimento,',
'                nom_atendimento,',
'                fk_atendimento_reservas_reservas,',
'                confirmado',
'            ) VALUES (',
'                SYSDATE,',
unistr('                ''Reserva confirmada para realiza\00E7\00E3o.'','),
'                v_nome,',
'                v_id_reserva,',
'                ''S''',
'            );',
'        END IF;',
'',
'    ELSIF v_acao = ''Cancelar'' THEN',
'        IF v_status_atual = ''Cancelado'' THEN',
unistr('            htp.p(''{"status":"erro","mensagem":"A reserva j\00E1 est\00E1 cancelada."}'');'),
'            RETURN;',
'        ELSE',
'            UPDATE reservas',
'            SET justificativa = v_justificativa,',
'                status = ''Cancelado''',
'            WHERE id_reserva = v_id_reserva;',
'',
'            -- Complementa o atendimento cancelando a reserva',
'            INSERT INTO atendimento_reservas (',
'                dat_criacao_atendimento,',
'                des_atendimento,',
'                nom_atendimento,',
'                fk_atendimento_reservas_reservas,',
'                confirmado',
'            ) VALUES (',
'                SYSDATE,',
'                ''Reserva cancelada, recusada.'',',
'                v_nome,',
'                v_id_reserva,',
'                ''N''',
'            );',
'        END IF;',
'    END IF;',
'',
'    COMMIT;',
'',
'    -- RESPOSTA JSON PARA EVITAR ERRO NO JAVASCRIPT',
'    htp.p(''{"status":"ok"}'');',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>182210249504461506
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(382983597758560455)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GERAR_URL_11'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('-- Cria a url para a p\00E1gina 11 com os par\00E2metros dessa p\00E1gina'),
'-- Passa o id_grupo para colapsar apenas esse grupo',
'DECLARE',
'    l_grupo_id VARCHAR2(100) := APEX_APPLICATION.G_X01;',
'    l_url      VARCHAR2(4000);',
'BEGIN',
'    l_url := apex_util.prepare_url(',
'        p_url => ''f?p='' || :APP_ID || '':11:'' || :APP_SESSION || ''::NO::P11_ID_GRUPO_ATIVO:'' || l_grupo_id',
'    );',
'',
'    -- Retorna a URL como JSON',
'    APEX_JSON.OPEN_OBJECT;',
'    APEX_JSON.WRITE(''url'', l_url);',
'    APEX_JSON.CLOSE_OBJECT;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>182210605520461510
);
end;
