,p_region_template_options=>'#DEFAULT#:t-Region--removeHeader js-removeLandmark:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT r.DAT_INICIO,',
'       r.DAT_FIM,',
'       r.TIP_RESERVAS,',
'       r.STATUS,',
'       case when MAX(r.NUM_PARTICIPANTES) is null then ''---'' else TO_CHAR(MAX(r.NUM_PARTICIPANTES)) end as NUM_PARTICIPANTES,',
'       r.TITULO_RESERVA,',
'       r.DES_RESERVA,',
'       LISTAGG(''- '' || LOC, ''<br>'')',
'            WITHIN GROUP (ORDER BY LOC) AS LOCAIS,',
'       case when max(r.OBS) is null then ''N/A'' else max(r.OBS) end as OBS',
'FROM RESERVAS r',
'JOIN (',
'    SELECT fk_atendimento_reservas_reservas, des_atendimento',
'    FROM (',
'        SELECT a.fk_atendimento_reservas_reservas,',
'            a.des_atendimento,',
'            ROW_NUMBER() OVER (',
'                PARTITION BY a.fk_atendimento_reservas_reservas',
'                ORDER BY a.dat_criacao_atendimento DESC, a.pk_atendimento_reservas DESC',
'            ) AS rn',
'        FROM atendimento_reservas a',
'    )',
'    WHERE rn = 1',
') ult',
'    ON r.id_reserva = ult.fk_atendimento_reservas_reservas',
'WHERE cod_grupo_reserva = :P202_COD_GRUPO_RESERVA',
unistr('    AND NVL(ult.des_atendimento, ''x'') <> ''Reserva cancelada pelo pr\00F3prio solicitante.'''),
'  group by',
'    r.titulo_reserva,',
'    r.des_reserva,',
'    r.tip_reservas,',
'    r.dat_inicio,',
'    r.dat_fim,',
'    r.status',
'  order by r.tip_reservas, r.dat_inicio',
'',
''))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P202_COD_GRUPO_RESERVA'
