wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(371075006553220960)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Confirmar escolhas e enviar email'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Envia email para o solicitante com os detalhes de cada reserva de tal grupo, assim como as respostas para cada reserva',
'DECLARE',
'    v_qtd_em_andamento  INTEGER;',
'    v_nome_solicitante  VARCHAR2(200);',
'    v_nome_asqualog     VARCHAR2(200);',
'    v_email_destino     VARCHAR2(200);',
'    v_email_remetente   VARCHAR2(200) := ''asqualog@senado.leg.br'';',
unistr('    v_assunto           VARCHAR2(200) := ''Atualiza\00E7\00E3o sobre suas reservas'';'),
'    v_mensagem          CLOB;',
'    v_bloco_reserva     CLOB;',
'    v_status_atual      VARCHAR2(50);',
'',
'    FUNCTION quebra_linha_html(p_texto CLOB) RETURN CLOB IS',
'        v_texto CLOB;',
'    BEGIN',
unistr('        -- quebra ap\00F3s ponto + mai\00FAscula'),
'        v_texto := REGEXP_REPLACE(',
'                     p_texto,',
unistr('                     ''\005C.\005Cs*([A-Z\00C1\00C9\00CD\00D3\00DA\00C2\00CA\00CE\00D4\00DB\00C3\00D5\00C7])'','),
'                     ''.<br>\1''',
'                   );',
'',
unistr('        -- adiciona recuo no in\00EDcio e ap\00F3s cada quebra'),
'        v_texto := ''&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;- '' ||',
'                   REPLACE(v_texto, ''<br>'', ''<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;- '');',
'',
'        RETURN v_texto;',
'    END;',
'',
'BEGIN',
'    SELECT COUNT(*) INTO v_qtd_em_andamento',
'    FROM reservas',
'    WHERE cod_grupo_reserva = :P202_COD_GRUPO_RESERVA',
'      AND status = ''Em Andamento'';',
'',
unistr('    -- S\00F3 \00E9 poss\00EDvel mandar o email quando todas as reservas do grupo forem analisadas'),
'    IF v_qtd_em_andamento > 0 THEN',
'        APEX_ERROR.ADD_ERROR(',
'            p_message => ''Ainda existem reservas para ser analisadas. Avalie todas as reservas do grupo antes de confirmar.'',',
'            p_display_location => APEX_ERROR.c_inline_in_notification',
'        );',
'        RETURN;',
'    END IF;',
'',
'    UPDATE reservas',
'    SET email_enviado = ''S''',
'    WHERE cod_grupo_reserva = :P202_COD_GRUPO_RESERVA;',
'',
'    BEGIN',
'        SELECT v.nom_pessoa',
'        INTO v_nome_solicitante',
'        FROM reservas r',
'        JOIN dda.vinculo_sf v',
'          ON v.num_cpf = LPAD(r.cod_pessoa, 11, ''0'')',
'         AND v.ind_vinculo_ativo = ''S''',
'        WHERE r.cod_grupo_reserva = :P202_COD_GRUPO_RESERVA',
'        FETCH FIRST 1 ROWS ONLY;',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            v_nome_solicitante := ''Solicitante Desconhecido'';',
'    END;',
'',
'    BEGIN',
'        SELECT nom_pessoa INTO v_nome_asqualog',
'        FROM dda.vinculo_sf',
'        WHERE num_cpf = ',
'            CASE',
'                WHEN REGEXP_LIKE(:APP_USER, ''^\d+$'')',
'                    THEN :APP_USER',
'                ELSE (',
'                    SELECT u.num_cpf_pessoa',
'                    FROM dda.usuario_rede u',
'                    WHERE LOWER(u.txt_email_sf) = LOWER(:APP_USER) || ''@senado.leg.br''',
'                )',
'            END',
'          AND ind_vinculo_ativo = ''S'';',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            v_nome_asqualog := ''Equipe ASQUALOG'';',
'    END;',
'',
'    BEGIN',
'        SELECT txt_email_sf INTO v_email_destino',
'        FROM dda.usuario_rede',
'        WHERE num_cpf_pessoa = (',
'            SELECT LPAD(cod_pessoa, 11, ''0'')',
'            FROM reservas',
'            WHERE cod_grupo_reserva = :P202_COD_GRUPO_RESERVA',
'            FETCH FIRST 1 ROWS ONLY',
'        )',
'          AND nom_situacao_login_ad = ''ATIVO'';',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            v_email_destino := ''sem_email@dominio.com'';',
'    END;',
'',
'    v_mensagem := ''<p>Prezado(a) <strong>'' || v_nome_solicitante || ''</strong>,</p>'' ||',
unistr('                  ''<p>Informamos que as reservas solicitadas por voc\00EA passaram por an\00E1lise e tivemos a seguinte decis\00E3o:</p>'';'),
'',
'    FOR rec IN (',
'        SELECT',
'               r.titulo_reserva,',
'               r.des_reserva,',
'               r.tip_reservas,',
'               r.num_participantes,',
'               TO_CHAR(r.dat_inicio, ''DD/MM/YYYY'') AS data_inicio,',
'               TO_CHAR(r.dat_fim, ''DD/MM/YYYY'') AS data_fim,',
'               MAX(CASE WHEN UPPER(r.status) = ''CONFIRMADO''',
'                    THEN r.justificativa END) motivo_confirmado,',
'               MAX(CASE WHEN UPPER(r.status) = ''CANCELADO''',
'                    THEN r.justificativa END) motivo_cancelado,',
'               LISTAGG(',
'                   CASE WHEN UPPER(r.status) = ''CONFIRMADO''',
'                        THEN ''&#8226; '' || r.loc END,',
'                   ''<br>''',
'               ) WITHIN GROUP (ORDER BY r.loc) locais_confirmados,',
'               LISTAGG(',
'                   CASE WHEN UPPER(r.status) = ''CANCELADO''',
'                        THEN ''&#8226; '' || r.loc END,',
'                   ''<br>''',
'               ) WITHIN GROUP (ORDER BY r.loc) locais_cancelados,',
'                (',
'                SELECT LISTAGG(',
'                           ''- '' || TO_CHAR(h.dat,''DD/MM/YYYY'') ||',
unistr('                           '' ('' || h.hor_inicio || '' \00E0s '' || h.hor_fim || '')'','),
'                           ''<br>''',
'                       ) WITHIN GROUP (ORDER BY h.dat, h.hor_inicio)',
'                FROM reservas r2',
'                JOIN horarios_mezanino h',
'                  ON h.id_reserva = r2.id_reserva',
'                WHERE r2.cod_grupo_reserva = :P202_COD_GRUPO_RESERVA',
'                  AND r2.titulo_reserva = r.titulo_reserva',
'                  AND r2.des_reserva    = r.des_reserva',
'                  AND r2.tip_reservas   = r.tip_reservas',
'                  AND r2.dat_inicio     = r.dat_inicio',
'                  AND r2.dat_fim        = r.dat_fim',
'            ) horarios_mezanino',
'        FROM reservas r',
'        JOIN (',
'            SELECT fk_atendimento_reservas_reservas',
'            FROM (',
'                SELECT',
'                    a.fk_atendimento_reservas_reservas,',
'                    a.des_atendimento,',
'                    ROW_NUMBER() OVER (',
'                        PARTITION BY a.fk_atendimento_reservas_reservas',
'                        ORDER BY a.dat_criacao_atendimento DESC,',
'                                 a.pk_atendimento_reservas DESC',
'                    ) rn',
'                FROM atendimento_reservas a',
'            )',
'            WHERE rn = 1',
unistr('              AND NVL(des_atendimento,''x'') <> ''Reserva cancelada pelo pr\00F3prio solicitante.'''),
'        ) ult',
'          ON ult.fk_atendimento_reservas_reservas = r.id_reserva',
'        WHERE r.cod_grupo_reserva = :P202_COD_GRUPO_RESERVA',
'        GROUP BY',
'            r.titulo_reserva,',
'            r.des_reserva,',
'            r.tip_reservas,',
'            r.dat_inicio,',
'            r.dat_fim,',
'            r.num_participantes',
'    ) LOOP',
'        v_bloco_reserva :=',
'            ''<hr>'' ||',
'            ''<strong>Nome do Evento:</strong> '' || rec.titulo_reserva || ''<br>'' ||',
unistr('            ''<strong>Descri\00E7\00E3o:</strong> '' || rec.des_reserva || ''<br>'' ||'),
'            ''<strong>Tipo:</strong> '' || rec.tip_reservas || ''<br>'' ||',
unistr('            ''<strong>Per\00EDodo:</strong> '' || rec.data_inicio || '' at\00E9 '' || rec.data_fim || ''<br><br>'';'),
'',
'        IF LOWER(rec.tip_reservas) LIKE ''%adesiv%'' THEN',
'            v_bloco_reserva := v_bloco_reserva ||',
unistr('                ''<strong><span style="color:green;">Resultado da An\00E1lise</span></strong><br>'' ||'),
'                CASE ',
'                    WHEN rec.motivo_confirmado IS NOT NULL THEN',
unistr('                        ''<strong>Observa\00E7\00E3o:</strong><br>'' ||'),
'                        quebra_linha_html(rec.motivo_confirmado)',
'                    WHEN rec.motivo_cancelado IS NOT NULL THEN',
'                        ''<strong>Motivo do Cancelamento:</strong><br>'' ||',
'                        quebra_linha_html(rec.motivo_cancelado)',
'                    ELSE',
unistr('                        ''Sem observa\00E7\00F5es.'''),
'                END || ''<br>'';',
'',
'        ELSE',
'            v_bloco_reserva := v_bloco_reserva ||',
'                ''<strong><span style="color:green;">Locais Confirmados</span></strong>'' ||',
'                CASE WHEN rec.motivo_confirmado IS NOT NULL',
unistr('                     THEN '': <strong>Observa\00E7\00E3o:</strong><br>'' ||'),
'                          quebra_linha_html(rec.motivo_confirmado)',
'                     ELSE '''' END ||',
'                ''<br>'' || NVL(rec.locais_confirmados,''- Nenhum'') || ''<br><br>'' ||',
'',
'                ''<strong><span style="color:red;">Locais Cancelados</span></strong>'' ||',
'                CASE WHEN rec.motivo_cancelado IS NOT NULL',
'                     THEN '': <br><strong>Motivo:</strong><br>'' ||',
'                          quebra_linha_html(rec.motivo_cancelado)',
'                     ELSE '''' END ||',
'                ''<br>'' || NVL(rec.locais_cancelados,''- Nenhum'') || ''<br>'';',
'        END IF;',
'        ',
'            IF LOWER(rec.tip_reservas) = ''mezanino''',
'               AND rec.horarios_mezanino IS NOT NULL THEN',
'                v_bloco_reserva := v_bloco_reserva ||',
unistr('                    ''<br><br><strong>Hor\00E1rios Reservados:</strong><br>'' ||'),
'                    rec.horarios_mezanino;',
'            END IF;',
'        v_mensagem := v_mensagem || v_bloco_reserva;',
'    END LOOP;',
'',
'    v_mensagem := v_mensagem ||',
unistr('                  ''<p>Agradecemos sua compreens\00E3o.</p>'' ||'),
'                  ''Atenciosamente,<br><br>'' ||',
'                    ''<b>'' || v_nome_asqualog || ''</b><br>'' ||',
unistr('                    ''Assessoria de Qualidade de Atendimento e Log\00EDstica \2013 ASQUALOG<br>'' ||'),
