wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(405997122319163361)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Cancelar Reserva'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('-- Cancelar reserva quando necess\00E1rio'),
'DECLARE',
'    v_nome              VARCHAR2(200);',
'    v_status            reservas.status%TYPE;',
'    v_email_remetente   VARCHAR2(200);',
'    v_email_destino     VARCHAR2(200);',
'    v_mensagem          CLOB;',
'BEGIN',
'    SELECT status INTO v_status',
'    FROM reservas',
'    WHERE id_reserva = :P204_ID_RESERVA;',
'',
'    IF v_status = ''Realizado'' THEN',
'        apex_error.add_error(',
unistr('            p_message => ''Voc\00EA n\00E3o pode cancelar uma reserva que j\00E1 foi realizada.'','),
'            p_display_location => apex_error.c_inline_in_notification',
'        );',
'    ELSIF v_status != ''Cancelado'' THEN',
'        UPDATE reservas',
'        SET status = ''Cancelado'',',
'            email_enviado = ''S'',',
'            justificativa = :P204_JUSTIFICATIVA',
'        WHERE id_reserva = :P204_ID_RESERVA;',
'',
'        IF :P204_TIP_RESERVAS = ''Mezanino'' THEN',
'            DELETE FROM horarios_mezanino',
'            WHERE id_reserva = :P204_ID_RESERVA;',
'        END IF;',
'',
'        SELECT nom_pessoa INTO v_nome',
'        FROM dda.vinculo_sf',
'        WHERE num_cpf = ',
'            CASE',
'                WHEN REGEXP_LIKE(:APP_USER, ''^\d+$'')',
'                    THEN :APP_USER',
'                ELSE (',
'                    SELECT u.num_cpf_pessoa',
'                    FROM dda.usuario_rede u',
'                    WHERE LOWER(u.txt_email_sf) = LOWER(:APP_USER) || ''@senado.leg.br''',
'                )',
'            END;',
'',
'        SELECT txt_email_sf INTO v_email_remetente',
'        FROM dda.usuario_rede',
'        WHERE num_cpf_pessoa = ',
'            CASE',
'                WHEN REGEXP_LIKE(:APP_USER, ''^\d+$'')',
'                    THEN :APP_USER',
'                ELSE (',
'                    SELECT u.num_cpf_pessoa',
'                    FROM dda.usuario_rede u',
'                    WHERE LOWER(u.txt_email_sf) = LOWER(:APP_USER) || ''@senado.leg.br''',
'                )',
'            END',
'          AND nom_situacao_login_ad = ''ATIVO'';',
'',
'        SELECT txt_email_sf INTO v_email_destino',
'        FROM dda.usuario_rede',
'        WHERE num_cpf_pessoa =  (',
'            SELECT LPAD(cod_pessoa, 11, ''0'')',
'            FROM reservas',
'            WHERE id_reserva = :P204_ID_RESERVA',
'        )',
'          AND nom_situacao_login_ad = ''ATIVO'';',
'',
'        INSERT INTO atendimento_reservas (',
'            dat_criacao_atendimento,',
'            des_atendimento,',
'            nom_atendimento,',
'            fk_atendimento_reservas_reservas,',
'            confirmado',
'        ) VALUES (',
'            SYSDATE,',
unistr('            ''Reserva cancelada pelo setor, por quest\00F5es da casa.'','),
'            v_nome,',
'            :P204_ID_RESERVA,',
'            ''N''',
'        );',
'',
'        v_mensagem := ''<p>Prezado(a),</p>'' ||',
'                      ''<p>Sua reserva foi <strong>cancelada</strong> pelo setor ASQUALOG.</p>'' ||',
'                      ''<p><strong>ID da Reserva:</strong> '' || :P204_ID_RESERVA || ''<br>'' ||',
'                      ''<strong>Tipo:</strong> '' || :P204_TIP_RESERVAS || ''<br>'' ||',
'                      ''<strong>Data/Hora do Cancelamento:</strong> '' || TO_CHAR(SYSDATE, ''DD/MM/YYYY HH24:MI'') || ''<br>'' ||',
unistr('                      ''<strong>Justificativa do setor:</strong> '' || NVL(:P204_JUSTIFICATIVA, ''N\00E3o informada'') || ''</p>'' ||'),
unistr('                      ''<p>Caso tenha d\00FAvidas, entre em contato com a equipe ASQUALOG.</p>'' ||'),
'                      ''<p>Atenciosamente,<br>'' || v_nome || ''<br>'' || v_email_remetente || ''</p>'';',
'',
'        APEX_MAIL.SEND (',
'            p_to        => v_email_destino,',
'            p_from      => v_email_remetente,',
'            p_subj      => ''Cancelamento de sua reserva - ID '' || :P204_ID_RESERVA,',
'            p_body      => NULL,',
'            p_body_html => v_mensagem',
'        );',
'',
'        COMMIT;',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(405997040215163360)
,p_internal_uid=>205224130081064416
);
