'        when regexp_like(:APP_USER, ''^\d+$'') then',
'          :APP_USER',
unistr('        -- sen\00E3o, busca o CPF pelo e-mail'),
'        else (',
'          select u.num_cpf_pessoa',
'            from dda.usuario_rede u',
'           where lower(u.txt_email_sf) =',
'                 lower(:APP_USER) || ''@senado.leg.br''',
'        )',
'      end',
'  and rownum = 1;',
''))
,p_item_default_type=>'SQL_QUERY'
,p_display_as=>'NATIVE_HIDDEN'
,p_attribute_01=>'Y'
