wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(125090448916809332)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Enviar Email com OS'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_email_usuario VARCHAR2(200);',
'    v_email_setor   VARCHAR2(200) := ''asqualog@senado.leg.br'';',
'',
'    v_body      CLOB := '''';',
'    v_usuario   VARCHAR2(200) := :P205_SOLICITANTE;',
'BEGIN',
'    SELECT txt_email_sf INTO v_email_usuario',
'    FROM dda.usuario_rede',
'    WHERE txt_login_ad = :APP_USER;',
'',
'    v_body := ''Prezados, '' || CHR(10) || CHR(10);',
'',
'    FOR r IN (',
'        SELECT',
'            TO_CHAR(',
'                CASE',
'                    WHEN TO_CHAR(dat_inicio, ''DY'', ''NLS_DATE_LANGUAGE=ENGLISH'') = ''MON'' THEN dat_inicio - 3 ',
'                    WHEN TO_CHAR(dat_inicio, ''DY'', ''NLS_DATE_LANGUAGE=ENGLISH'') = ''SUN'' THEN dat_inicio - 2',
'                    ELSE dat_inicio - 1',
'                END,',
'            ''DD/MM/YYYY'') ',
'            || '', '' ||',
'            TRIM(TO_CHAR(',
'                CASE',
'                    WHEN TO_CHAR(dat_inicio, ''DY'', ''NLS_DATE_LANGUAGE=ENGLISH'') = ''MON'' THEN dat_inicio - 3 ',
'                    WHEN TO_CHAR(dat_inicio, ''DY'', ''NLS_DATE_LANGUAGE=ENGLISH'') = ''SUN'' THEN dat_inicio - 2',
'                    ELSE dat_inicio - 1',
'                END,',
'            ''day'',',
'            ''NLS_DATE_LANGUAGE=PORTUGUESE'')) AS data_pre,',
'',
'            TO_CHAR(',
'                CASE',
'                    WHEN TO_CHAR(dat_fim, ''DY'', ''NLS_DATE_LANGUAGE=ENGLISH'') = ''FRI'' THEN dat_fim + 3 ',
'                    WHEN TO_CHAR(dat_fim, ''DY'', ''NLS_DATE_LANGUAGE=ENGLISH'') = ''SAT'' THEN dat_fim + 2',
'                    ELSE dat_fim + 1',
'                END,',
'            ''DD/MM/YYYY'') ',
'            || '', '' ||',
'            TRIM(TO_CHAR(',
'                CASE',
'                    WHEN TO_CHAR(dat_fim, ''DY'', ''NLS_DATE_LANGUAGE=ENGLISH'') = ''FRI'' THEN dat_fim + 3 ',
'                    WHEN TO_CHAR(dat_fim, ''DY'', ''NLS_DATE_LANGUAGE=ENGLISH'') = ''SAT'' THEN dat_fim + 2',
'                    ELSE dat_fim + 1',
'                END,',
'            ''day'',',
'            ''NLS_DATE_LANGUAGE=PORTUGUESE'')) AS data_pos,',
'',
'            COUNT(loc) AS qtd,',
'',
'            LISTAGG(''- '' || loc, CHR(10))',
'                WITHIN GROUP (ORDER BY loc) AS locais,',
'',
'            TO_CHAR(dat_inicio, ''DD/MM/YYYY'') AS data_inicio,',
'            TO_CHAR(dat_fim, ''DD/MM/YYYY'') AS data_termino,',
'            titulo_reserva AS titulo,',
'',
'            CASE tip_reservas',
'                WHEN ''Porta-Banner'' THEN ''Porta-Banner(s)''',
'                WHEN ''Porta-Cartaz'' THEN ''Porta-Cartaz(es)''',
'            END AS tipo',
'',
'        FROM reservas',
'        WHERE cod_grupo_reserva = :P205_ID_GRUPO',
'        GROUP BY',
'            titulo_reserva,',
'            des_reserva,',
'            tip_reservas,',
'            dat_inicio,',
'            dat_fim',
'        ORDER BY dat_inicio',
'    )',
'    LOOP',
'        v_body := v_body ||',
'            ''Solicito que providenciem para dia '' || r.data_pre ||',
unistr('            '', no per\00EDodo da tarde, o remanejamento de '' || r.qtd || '' '' || r.tipo ||'),
'            '' para os seguintes locais: '' || CHR(10) ||',
'                r.locais || CHR(10) || CHR(10) ||',
'            ',
unistr('            ''Esses '' || r.tipo || '' ser\00E3o usados para divulgar '' || r.titulo ||'),
unistr('            '', no per\00EDodo de '' || r.data_inicio || '' a '' || r.data_termino || ''.'' || CHR(10) || CHR(10) ||'),
'',
unistr('            ''Favor j\00E1 deixar agendado a retirada dos adesivos no dia '' || r.data_pos ||'),
unistr('            '', pela manh\00E3, e em seguida o recolhimento para o dep\00F3sito.'' ||'),
'',
'            CHR(10) || CHR(10) || ''------------------------------------------------------------'' || CHR(10) || CHR(10); ',
'    END LOOP;',
'',
'    v_body := v_body ||',
'                ''Atenciosamente, '' || CHR(10) || v_usuario;',
'    ',
'    APEX_MAIL.SEND(',
'        p_to        => v_email_usuario,',
'        p_from      => v_email_setor,',
unistr('        p_subj      => ''Texto para a abertura da OS para realoca\00E7\00E3o dos totens'','),
'        p_body      => v_body',
'    );',
'',
'    APEX_MAIL.PUSH_QUEUE;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>125090448916809332
);
end;
